  (id,subject_key,year,academic_year,week,session,duration_minutes,sp_code,printed_pages,content_sha256,reviewed_blocks_sha256,approval_manifest_sha256,approval_status,active,lesson,reviewed_blocks,limits)
values
  ('PJ1-2026B-2S-W36-S2','pj',1,2026,36,2,30,'3.3.1',array[52,53,54,55]::int[],'ab3e48b73f17cd0138e153d7b5097d2604a0de9fbced184fcab63bab1774699e','c070a965cb1a0a5b98a1fc470bfc09c1851cf2bea71b99a8b1e88ec835a7f982','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W36-S2", "subject": "Pendidikan Jasmani", "year": 1, "week": 36, "session": 2, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Tenang-tenang", "source_title": "Tenang-tenang", "unit": "Unit 8: Cergas dan Mantap", "source_row_id": "PJ1-RPT2026-T13-R2", "source_row_literal": ["36\n\nKump A: 11.10.2026-15.10.2026\n\nKump B:\n12.10.2026-16.10.2026", "8: CERGAS DAN MANTAP\n\nTENANG-TENANG", "3.3 Melakukan senaman kelenturan dengan lakuan yang betul.\n4.3 Mengaplikasi konsep asas kelenturan\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "3.3.1  Melakukan aktiviti regangan dinamik dan statik pada otot-otot utama.\n\n4.3.1 Mengenal pasti cara regangan yang betul.\n\n4.3.2  Mengenali pelbagai pergerakan yang betul untuk meningkatkan kelenturan pada sesuatu kumpulan otot.\n\n4.3.3  Mengetahui bahawa aktiviti regangan dapat meningkatkan kecekapan fungsi otot.\n\n5.1.3  Mematuhi arahan guru dan mengenal peraturan keselamatan di tempat melakukan aktiviti.", "Pemerhatian /\nPentaksiran\n\nPermainan kecil:\nRegangan rahsia\n\n\nBT m/s 54-55"], "rpt_original_page_literal": "54-55", "source_pages": [52, 53, 54, 55], "source_pdf_pages": [60, 61, 62, 63], "rpt_book_pages": "52, 53, 54, 55", "main_standard_key": "3.3.1", "sk_code": "3.3", "sk_text": "Melakukan senaman kelenturan dengan lakuan yang betul.", "sp_code": "3.3.1", "sp_text": "Melakukan senaman regangan dinamik dan statik pada sendi-sendi utama.", "complementary_standards": [{"standard_key": "4.3.1", "sp_code": "4.3.1", "sp_text": "Mengenal pasti cara regangan yang betul.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "PJ1-DSKP-P82-L16", "sp_code": "4.3.2", "sp_text": "Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Jenis regangan; kod tercetak pertama"}, {"standard_key": "PJ1-DSKP-P82-L18", "sp_code": "4.3.2", "sp_text": "Menyatakan tujuan melakukan senaman regangan.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Tujuan regangan; kod tercetak kedua"}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "source_task": "Mengawal regangan sisi dan bahagian atas badan", "authoring_focus": "Mengawal regangan sisi dan bahagian atas badan", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "RPT menumpukan statik BT54–55; dinamik BT52–53 digunakan dalam sesi juga. Dua pernyataan 4.3.2 tercetak dikekalkan; nombor RPT4.3.3 ditanda konflik. Regangan lembut kiri/kanan tanpa henjutan, tarikan pasangan atau sasaran sakit. SP5.1.3 digunakan mengikut ayat rasmi DSKP, bukan gabungan ayat keselamatan lama RPT.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": true, "source_code_note": "DSKP hlm70/PDF82 mencetak 4.3.2 dua kali: mengenal jenis regangan dan menyatakan tujuan. Kedua-dua pernyataan dikekalkan; kod4.3.3 dalam RPT/buku belum disahkan sebagai kod unik DSKP.", "unperformed_literal_elements": ["RPT4.3.3: padanan kod unik belum disahkan; tujuan diajar melalui pernyataan4.3.2 kedua yang tercetak."], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Regangan hanya dalam julat selesa. Berhenti jika sakit, kebas atau pening; tiada sentapan, henjutan atau menahan nafas.", "Murid tidak menarik, menekan atau menolak anggota rakan. Bantuan guru berupa contoh dan arahan, bukan memaksa julat.", "Gerakan bahu dan lutut kecil serta terkawal. Tiada pusingan penuh leher, lentikan belakang melampau atau pertandingan paling lentur.", "Tahan statik kira-kira 10 saat sebagai cadangan guru; boleh dilepaskan lebih awal. Tempoh ini bukan sasaran wajib DSKP atau jaminan sakit otot hilang."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Regangan bahu, sisi badan dan pelepasan perlahan", "objective": "Murid dapat melakukan regangan dinamik dan statik dengan mengekalkan kawalan tubuh.", "success_criteria": ["Melakukan dinamik tangan dan kilas kecil serta statik bahu dan sisi badan pada dua sisi.", "Mengenal jenis serta tujuan regangan dan mengikut arahan berhenti."], "prior_knowledge": "Murid pernah melakukan statik selepas dinamik; guru mengulang had julat yang selesa.", "equipment": [{"item": "Kon penanda", "quantity": "Empat kon di luar tempat pijakan.", "use": "Menandakan sempadan; bukan halangan untuk dilompat."}, {"item": "Jam guru dan buku teks", "quantity": "Satu jam; BT52–55 sebagai rujukan guru.", "use": "Mengurus masa gerakan serta membezakan regangan dinamik dan statik."}, {"item": "Air minuman sendiri", "quantity": "Satu botol setiap murid mengikut keperluan.", "use": "Rehat dan minum sebelum, semasa serta selepas aktiviti."}], "preparation": ["Tetapkan ruang cukup untuk tangan bergerak dan kon di luar tempat pijakan.", "Pilih membuka/merapatkan tangan serta kilas kecil berpandukan gerakan BT52–53.", "Contoh guru statik bahu ialah lengan merentas dada. Statik sisi badan ialah angkat satu tangan setakat selesa dan condong sedikit ke sisi bertentangan, tanpa melentik ke belakang."], "organisation": ["Murid kekal berdiri dalam ruang sendiri. Pasangan melihat dari sisi tanpa menyentuh atau menarik anggota.", "Latihan kelas merangkumi dinamik serta kedua-dua statik. Semakan A/B memberi giliran sendiri tanpa menambah blok masa.", "Guru membenarkan tangan lebih rendah dan condongan lebih kecil atau rehat. Catat penyesuaian, bukan memaksa posisi."], "movement_cues": ["Dinamik tangan: buka dan rapatkan tangan perlahan tanpa menyentap bahu.", "Kilas badan kecil: kaki kekal selesa menghadap depan, tangan dekat pinggang; pusing dada sedikit kanan/kiri tanpa menghentak lutut.", "Statik bahu: bawa satu lengan melintas dada dengan sokongan ringan tangan sendiri pada lengan atas, bukan sendi siku; tukar sisi.", "Statik sisi badan: angkat satu tangan selesa, condong sedikit ke sisi bertentangan tanpa mengangkat tumit atau melentik pinggang. Lepas perlahan dan tukar sisi.", "Dinamik melibatkan gerakan, statik mengekalkan posisi. Tujuannya membantu kelenturan dan pergerakan, bukan memaksa rasa sakit atau paling lentur."], "timing_note": "Empat ulangan dinamik dan statik sekitar 10 saat hanyalah cadangan guru. Rehat, peralihan, minum dan penyejukan termasuk dalam 30 minit.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Condong sedikit sahaja. Lepaskan perlahan sebelum bertukar sisi.", "pupils_do": "Murid melakukan regangan sisi dengan julat kecil dan kembali tegak tanpa sentapan.", "teacher_checks": "Guru semak tiada lentikan belakang atau tarikan pasangan."}, "bbm": ["Kon penanda — Empat kon di luar tempat pijakan.", "Jam guru dan buku teks — Satu jam; BT52–55 sebagai rujukan guru.", "Air minuman sendiri — Satu botol setiap murid mengikut keperluan.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Kon penanda", "Jam guru dan buku teks", "Air minuman sendiri"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Tunjuk kawalan dan pelepasan", "minutes": 4, "teacher": ["Guru menunjukkan buka/rapat tangan dan kilas kecil sebagai dinamik.", "Guru menunjukkan silang dada serta condongan sisi statik. Bezakan condong ke sisi dengan melentik ke belakang."], "pupils": ["Murid meniru julat kecil yang selesa.", "Murid menamakan dinamik dan statik apabila guru bertanya."], "check": "Kawalan dan perbezaan jenis dipastikan sebelum latihan.", "resources": ["Ruang sendiri"]}, {"name": "Dinamik dan tahan dua sisi", "minutes": 9, "teacher": ["Gunakan tiga minit bagi dua dinamik perlahan dengan rehat pendek.", "Beri satu minit rehat/minum.", "Gunakan empat minit untuk statik bahu dan sisi badan kiri/kanan, dilepas perlahan antara tahan.", "Gunakan minit akhir untuk mendengar tujuan regangan dan menyemak ketidakselesaan."], "pupils": ["Murid menggerakkan tangan dan kilas badan sedikit.", "Murid berhenti dan melakukan statik bahu serta sisi badan dengan nafas biasa.", "Murid melepaskan regangan perlahan dan memaklumkan jika sakit."], "check": "Guru menjejak kedua-dua jenis dan dua sisi tanpa sasaran julat.", "resources": ["Jam guru", "Air sendiri", "Kon di tepi"]}, {"name": "Pasangan semak satu petunjuk", "minutes": 7, "teacher": ["Beri dua minit untuk A dan dua minit untuk B menunjukkan satu dinamik serta dua statik.", "Beri satu minit rehat dan dua minit soal jawab jenis, tujuan serta arahan berhenti.", "Minta pasangan memberi pesanan lisan sahaja, seperti perlahan, tanpa membetulkan tubuh dengan tangan."], "pupils": ["Murid menjalani giliran sendiri.", "Murid menunggu dan memberi satu peringatan lisan yang sopan.", "Murid menyebut jenis dan tujuan serta satu petunjuk kawalan yang diamalkan."], "check": "PBD meliputi lakuan, dua rekod 4.3.2 dan kepatuhan arahan.", "resources": ["Ruang sendiri", "Senarai guru"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Melakukan dinamik dan statik bahu/sisi dengan contoh kecil guru.", "materials": ["Ruang sendiri"], "teacher": ["Benarkan tangan lebih rendah atau rehat jika tidak selesa.", "Tunjukkan satu gerakan pada satu masa dan beri kata mula tujuan."], "pupil_steps": ["Buka/rapat tangan dan kilas sedikit sebagai dinamik.", "Lakukan silang dada statik pada dua sisi dengan sokongan tangan sendiri.", "Lakukan statik sisi badan kecil pada kiri/kanan dan lepaskan perlahan.", "Sebut dinamik bergerak, statik ditahan serta tujuan membantu kelenturan."], "product": "Dinamik dan dua statik sendiri serta jawapan ringkas.", "criterion": "Gerakan selamat dan kedua-dua jenis dicuba; bantuan serta bahagian tertangguh dicatat.", "next_step": "Ulang gerakan paling selesa, bukan memaksa tangan tinggi.", "example": {"teacher": "Perlu condong jauh?", "pupil": "Tidak. Sedikit dan setakat selesa."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Mengawal urutan dinamik sebelum statik bahu dan sisi.", "materials": ["Ruang pasangan"], "teacher": ["Semak kaki dan bahu melalui penerangan, bukan tekanan.", "Tanya jenis dan tujuan selepas murid melepaskan posisi."], "pupil_steps": ["Lakukan dua dinamik perlahan.", "Lakukan statik silang dada kiri/kanan.", "Lakukan statik sisi badan dan kembali tegak sebelum tukar sisi.", "Nyatakan jenis, tujuan dan ikut arahan berhenti."], "product": "Urutan sendiri serta penerangan jenis dan tujuan.", "criterion": "Kedua-dua jenis terkawal tanpa lentik belakang atau henjutan.", "next_step": "Perkemas cara kembali tegak jika perlu.", "example": {"teacher": "Apa dibuat selepas tahan regangan?", "pupil": "Lepaskan perlahan sebelum tukar sisi."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas peralihan dan pelepasan tanpa menambah julat.", "materials": ["Ruang sendiri"], "teacher": ["Pilih satu sasaran kecil: kembali tegak dengan tenang.", "Kekalkan jumlah ulangan serta masa yang sama."], "pupil_steps": ["Lakukan dinamik tangan dan kilas kecil.", "Berhenti sebelum silang dada statik.", "Lakukan statik sisi dan kembali tegak perlahan pada kedua-dua sisi.", "Sebut tujuan, kenal dinamik/statik dan jelaskan satu pembaikan kawalan."], "product": "Dinamik, statik dan satu pembaikan terkawal.", "criterion": "Kawalan diperbaik dalam julat selesa; jenis dan tujuan dinilai sendiri.", "next_step": "Kekalkan petunjuk yang membantu pada sesi seterusnya.", "example": {"teacher": "Apakah perubahan yang kamu buat?", "pupil": "Saya berhenti dahulu dan kembali tegak perlahan."}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan regangan dinamik dan statik dengan mengekalkan kawalan tubuh.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bimbing julat Peneroka.", "Semak dua sisi Pembina.", "Perhatikan pelepasan Pencabar tanpa menambah beban."], "individual_check": "Melakukan dinamik tangan dan kilas kecil serta statik bahu dan sisi badan pada dua sisi.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian individu semasa latihan dan giliran pasangan.", "evidence": "Lakuan dinamik dan statik tangan, bahu dan sisi badan murid sendiri.", "criterion": "Kedua-dua jenis dilakukan dengan kawalan dan tanpa sakit. Bantuan, tempoh sebenar dan bahagian belum dibuat dicatat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Dinamik: ____", "Statik: ____", "Kiri/kanan jika berkaitan: ____", "Bantuan / belum diperhatikan: ____"]}, "pbd_complementary": {"4.3.1": {"method": "Pemerhatian dan soalan ringkas tentang teknik.", "evidence": "Murid menunjukkan satu cara selamat ketika tangan, bahu dan sisi badan.", "criterion": "Gerakan kecil atau tahan tanpa henjutan dikenal; tidak menarik rakan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Cara selamat ditunjukkan: ____", "Bantuan / belum dilihat: ____"]}, "PJ1-DSKP-P82-L16": {"method": "Soal jawab individu selepas bergerak.", "evidence": "Murid mengenal mana gerakan dinamik dan mana regangan statik yang telah dilakukan.", "criterion": "Kedua-dua jenis dikenal melalui bergerak terkawal dan mengekalkan posisi. Ini pernyataan pertama berkod 4.3.2.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Dinamik dikenal: ____", "Statik dikenal: ____", "Bantuan: ____"]}, "PJ1-DSKP-P82-L18": {"method": "Soalan tujuan dengan kata mudah.", "evidence": "Murid menyebut tujuan regangan bagi tangan, bahu dan sisi badan.", "criterion": "Murid menyebut membantu kelenturan atau memudahkan gerakan. Ini pernyataan kedua berkod 4.3.2; bukan kod DSKP 4.3.3 yang direka.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Tujuan yang disebut: ____", "Kata bantu / belum didengar: ____"]}, "5.1.3": {"method": "Pemerhatian dan respons individu sepanjang latihan.", "evidence": "Tindakan mula, berhenti dan menjaga ruang mengikut arahan.", "criterion": "Arahan dipatuhi dengan bantuan; berhenti kerana sakit ialah tindakan selamat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Respons atau tindakan sebenar: ____", "Bantuan / rehat / belum dilihat: ____"]}}, "intervention": ["Jika condongan sisi tidak selesa, hentikan bahagian itu dan rekod belum dilaksanakan; guru menentukan penyesuaian seterusnya.", "Ulang jenis dan tujuan melalui dua soalan berasingan supaya rekod kod berulang tidak menghapuskan salah satu hasil."], "book_pages_text": "52, 53, 54, 55", "sp_focus": "", "sp_display": "3.3.1", "complementary": [{"standard_key": "4.3.1", "sp_code": "4.3.1", "sp_text": "Mengenal pasti cara regangan yang betul.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "PJ1-DSKP-P82-L16", "sp_code": "4.3.2", "sp_text": "Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Jenis regangan; kod tercetak pertama"}, {"standard_key": "PJ1-DSKP-P82-L18", "sp_code": "4.3.2", "sp_text": "Menyatakan tujuan melakukan senaman regangan.", "sk_code": "4.3", "sk_text": "Mengaplikasi konsep asas kelenturan.", "domain": "kognitif", "source_label": "Tujuan regangan; kod tercetak kedua"}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "draft_sha256": "06d8f735d15e510696017693fd88945380d84e64f64bd9f5fd8d0f9b999d2f72"}'::jsonb,'[{"kind": "title", "text": "Minggu 36 Sesi 2 — Regangan bahu, sisi badan dan pelepasan perlahan"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W36-S2"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 8: Cergas dan Mantap"}, {"kind": "p", "text": "Tajuk buku teks: Tenang-tenang"}, {"kind": "p", "text": "Aktiviti guru: Regangan bahu, sisi badan dan pelepasan perlahan"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 52, 53, 54, 55."}, {"kind": "p", "text": "Empat ulangan dinamik dan statik sekitar 10 saat hanyalah cadangan guru. Rehat, peralihan, minum dan penyejukan termasuk dalam 30 minit."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.3: Melakukan senaman kelenturan dengan lakuan yang betul."}, {"kind": "p", "text": "SP utama 3.3.1: Melakukan senaman regangan dinamik dan statik pada sendi-sendi utama."}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.1: Mengenal pasti cara regangan yang betul."}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.2: Mengenal pasti senaman regangan statik dan dinamik pada sendi-sendi utama."}, {"kind": "p", "text": "Pengenal pernyataan sumber: Jenis regangan; kod tercetak pertama"}, {"kind": "p", "text": "SK sokongan 4.3: Mengaplikasi konsep asas kelenturan."}, {"kind": "p", "text": "SP sokongan 4.3.2: Menyatakan tujuan melakukan senaman regangan."}, {"kind": "p", "text": "Pengenal pernyataan sumber: Tujuan regangan; kod tercetak kedua"}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.3: Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "DSKP hlm70/PDF82 mencetak 4.3.2 dua kali: mengenal jenis regangan dan menyatakan tujuan. Kedua-dua pernyataan dikekalkan; kod4.3.3 dalam RPT/buku belum disahkan sebagai kod unik DSKP."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan regangan dinamik dan statik dengan mengekalkan kawalan tubuh."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Melakukan dinamik tangan dan kilas kecil serta statik bahu dan sisi badan pada dua sisi."}, {"kind": "p", "text": "2. Mengenal jenis serta tujuan regangan dan mengikut arahan berhenti."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah melakukan statik selepas dinamik; guru mengulang had julat yang selesa."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: Empat kon di luar tempat pijakan."}, {"kind": "p", "text": "Kegunaan: Menandakan sempadan; bukan halangan untuk dilompat."}, {"kind": "label", "text": "Jam guru dan buku teks"}, {"kind": "p", "text": "Keperluan: Satu jam; BT52–55 sebagai rujukan guru."}, {"kind": "p", "text": "Kegunaan: Mengurus masa gerakan serta membezakan regangan dinamik dan statik."}, {"kind": "label", "text": "Air minuman sendiri"}, {"kind": "p", "text": "Keperluan: Satu botol setiap murid mengikut keperluan."}, {"kind": "p", "text": "Kegunaan: Rehat dan minum sebelum, semasa serta selepas aktiviti."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Tetapkan ruang cukup untuk tangan bergerak dan kon di luar tempat pijakan."}, {"kind": "p", "text": "2. Pilih membuka/merapatkan tangan serta kilas kecil berpandukan gerakan BT52–53."}, {"kind": "p", "text": "3. Contoh guru statik bahu ialah lengan merentas dada. Statik sisi badan ialah angkat satu tangan setakat selesa dan condong sedikit ke sisi bertentangan, tanpa melentik ke belakang."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Murid kekal berdiri dalam ruang sendiri. Pasangan melihat dari sisi tanpa menyentuh atau menarik anggota."}, {"kind": "p", "text": "2. Latihan kelas merangkumi dinamik serta kedua-dua statik. Semakan A/B memberi giliran sendiri tanpa menambah blok masa."}, {"kind": "p", "text": "3. Guru membenarkan tangan lebih rendah dan condongan lebih kecil atau rehat. Catat penyesuaian, bukan memaksa posisi."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Dinamik tangan: buka dan rapatkan tangan perlahan tanpa menyentap bahu."}, {"kind": "p", "text": "2. Kilas badan kecil: kaki kekal selesa menghadap depan, tangan dekat pinggang; pusing dada sedikit kanan/kiri tanpa menghentak lutut."}, {"kind": "p", "text": "3. Statik bahu: bawa satu lengan melintas dada dengan sokongan ringan tangan sendiri pada lengan atas, bukan sendi siku; tukar sisi."}, {"kind": "p", "text": "4. Statik sisi badan: angkat satu tangan selesa, condong sedikit ke sisi bertentangan tanpa mengangkat tumit atau melentik pinggang. Lepas perlahan dan tukar sisi."}, {"kind": "p", "text": "5. Dinamik melibatkan gerakan, statik mengekalkan posisi. Tujuannya membantu kelenturan dan pergerakan, bukan memaksa rasa sakit atau paling lentur."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — Empat kon di luar tempat pijakan."}, {"kind": "p", "text": "2. Jam guru dan buku teks — Satu jam; BT52–55 sebagai rujukan guru."}, {"kind": "p", "text": "3. Air minuman sendiri — Satu botol setiap murid mengikut keperluan."}, {"kind": "p", "text": "4. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Regangan hanya dalam julat selesa. Berhenti jika sakit, kebas atau pening; tiada sentapan, henjutan atau menahan nafas."}, {"kind": "p", "text": "5. Murid tidak menarik, menekan atau menolak anggota rakan. Bantuan guru berupa contoh dan arahan, bukan memaksa julat."}, {"kind": "p", "text": "6. Gerakan bahu dan lutut kecil serta terkawal. Tiada pusingan penuh leher, lentikan belakang melampau atau pertandingan paling lentur."}, {"kind": "p", "text": "7. Tahan statik kira-kira 10 saat sebagai cadangan guru; boleh dilepaskan lebih awal. Tempoh ini bukan sasaran wajib DSKP atau jaminan sakit otot hilang."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Kon penanda Jam guru dan buku teks Air minuman sendiri"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Tunjuk kawalan dan pelepasan — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan buka/rapat tangan dan kilas kecil sebagai dinamik."}, {"kind": "p", "text": "2. Guru menunjukkan silang dada serta condongan sisi statik. Bezakan condong ke sisi dengan melentik ke belakang."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meniru julat kecil yang selesa."}, {"kind": "p", "text": "2. Murid menamakan dinamik dan statik apabila guru bertanya."}, {"kind": "p", "text": "Semakan: Kawalan dan perbezaan jenis dipastikan sebelum latihan."}, {"kind": "p", "text": "Alatan: Ruang sendiri"}, {"kind": "h3", "text": "Langkah 4: Dinamik dan tahan dua sisi — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Gunakan tiga minit bagi dua dinamik perlahan dengan rehat pendek."}, {"kind": "p", "text": "2. Beri satu minit rehat/minum."}, {"kind": "p", "text": "3. Gunakan empat minit untuk statik bahu dan sisi badan kiri/kanan, dilepas perlahan antara tahan."}, {"kind": "p", "text": "4. Gunakan minit akhir untuk mendengar tujuan regangan dan menyemak ketidakselesaan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menggerakkan tangan dan kilas badan sedikit."}, {"kind": "p", "text": "2. Murid berhenti dan melakukan statik bahu serta sisi badan dengan nafas biasa."}, {"kind": "p", "text": "3. Murid melepaskan regangan perlahan dan memaklumkan jika sakit."}, {"kind": "p", "text": "Semakan: Guru menjejak kedua-dua jenis dan dua sisi tanpa sasaran julat."}, {"kind": "p", "text": "Alatan: Jam guru Air sendiri Kon di tepi"}, {"kind": "h3", "text": "Langkah 5: Pasangan semak satu petunjuk — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Beri dua minit untuk A dan dua minit untuk B menunjukkan satu dinamik serta dua statik."}, {"kind": "p", "text": "2. Beri satu minit rehat dan dua minit soal jawab jenis, tujuan serta arahan berhenti."}, {"kind": "p", "text": "3. Minta pasangan memberi pesanan lisan sahaja, seperti perlahan, tanpa membetulkan tubuh dengan tangan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menjalani giliran sendiri."}, {"kind": "p", "text": "2. Murid menunggu dan memberi satu peringatan lisan yang sopan."}, {"kind": "p", "text": "3. Murid menyebut jenis dan tujuan serta satu petunjuk kawalan yang diamalkan."}, {"kind": "p", "text": "Semakan: PBD meliputi lakuan, dua rekod 4.3.2 dan kepatuhan arahan."}, {"kind": "p", "text": "Alatan: Ruang sendiri Senarai guru"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Condong sedikit sahaja. Lepaskan perlahan sebelum bertukar sisi."}, {"kind": "p", "text": "Murid: Murid melakukan regangan sisi dengan julat kecil dan kembali tegak tanpa sentapan."}, {"kind": "p", "text": "Semakan guru: Guru semak tiada lentikan belakang atau tarikan pasangan."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W36-S2"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan regangan dinamik dan statik dengan mengekalkan kawalan tubuh."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bimbing julat Peneroka."}, {"kind": "p", "text": "2. Semak dua sisi Pembina."}, {"kind": "p", "text": "3. Perhatikan pelepasan Pencabar tanpa menambah beban."}, {"kind": "p", "text": "Semakan individu: Melakukan dinamik tangan dan kilas kecil serta statik bahu dan sisi badan pada dua sisi."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Melakukan dinamik dan statik bahu/sisi dengan contoh kecil guru."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Benarkan tangan lebih rendah atau rehat jika tidak selesa."}, {"kind": "p", "text": "2. Tunjukkan satu gerakan pada satu masa dan beri kata mula tujuan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Buka/rapat tangan dan kilas sedikit sebagai dinamik."}, {"kind": "p", "text": "2. Lakukan silang dada statik pada dua sisi dengan sokongan tangan sendiri."}, {"kind": "p", "text": "3. Lakukan statik sisi badan kecil pada kiri/kanan dan lepaskan perlahan."}, {"kind": "p", "text": "4. Sebut dinamik bergerak, statik ditahan serta tujuan membantu kelenturan."}, {"kind": "p", "text": "Contoh guru: Perlu condong jauh?"}, {"kind": "p", "text": "Contoh respons murid: Tidak. Sedikit dan setakat selesa."}, {"kind": "p", "text": "Hasil individu: Dinamik dan dua statik sendiri serta jawapan ringkas."}, {"kind": "p", "text": "Kriteria: Gerakan selamat dan kedua-dua jenis dicuba; bantuan serta bahagian tertangguh dicatat."}, {"kind": "p", "text": "Susulan: Ulang gerakan paling selesa, bukan memaksa tangan tinggi."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Mengawal urutan dinamik sebelum statik bahu dan sisi."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang pasangan"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Semak kaki dan bahu melalui penerangan, bukan tekanan."}, {"kind": "p", "text": "2. Tanya jenis dan tujuan selepas murid melepaskan posisi."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Lakukan dua dinamik perlahan."}, {"kind": "p", "text": "2. Lakukan statik silang dada kiri/kanan."}, {"kind": "p", "text": "3. Lakukan statik sisi badan dan kembali tegak sebelum tukar sisi."}, {"kind": "p", "text": "4. Nyatakan jenis, tujuan dan ikut arahan berhenti."}, {"kind": "p", "text": "Contoh guru: Apa dibuat selepas tahan regangan?"}, {"kind": "p", "text": "Contoh respons murid: Lepaskan perlahan sebelum tukar sisi."}, {"kind": "p", "text": "Hasil individu: Urutan sendiri serta penerangan jenis dan tujuan."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis terkawal tanpa lentik belakang atau henjutan."}, {"kind": "p", "text": "Susulan: Perkemas cara kembali tegak jika perlu."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas peralihan dan pelepasan tanpa menambah julat."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Pilih satu sasaran kecil: kembali tegak dengan tenang."}, {"kind": "p", "text": "2. Kekalkan jumlah ulangan serta masa yang sama."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Lakukan dinamik tangan dan kilas kecil."}, {"kind": "p", "text": "2. Berhenti sebelum silang dada statik."}, {"kind": "p", "text": "3. Lakukan statik sisi dan kembali tegak perlahan pada kedua-dua sisi."}, {"kind": "p", "text": "4. Sebut tujuan, kenal dinamik/statik dan jelaskan satu pembaikan kawalan."}, {"kind": "p", "text": "Contoh guru: Apakah perubahan yang kamu buat?"}, {"kind": "p", "text": "Contoh respons murid: Saya berhenti dahulu dan kembali tegak perlahan."}, {"kind": "p", "text": "Hasil individu: Dinamik, statik dan satu pembaikan terkawal."}, {"kind": "p", "text": "Kriteria: Kawalan diperbaik dalam julat selesa; jenis dan tujuan dinilai sendiri."}, {"kind": "p", "text": "Susulan: Kekalkan petunjuk yang membantu pada sesi seterusnya."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.3.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian individu semasa latihan dan giliran pasangan."}, {"kind": "p", "text": "Bukti: Lakuan dinamik dan statik tangan, bahu dan sisi badan murid sendiri."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis dilakukan dengan kawalan dan tanpa sakit. Bantuan, tempoh sebenar dan bahagian belum dibuat dicatat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Dinamik: ____"}, {"kind": "p", "text": "2. Statik: ____"}, {"kind": "p", "text": "3. Kiri/kanan jika berkaitan: ____"}, {"kind": "p", "text": "4. Bantuan / belum diperhatikan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian dan soalan ringkas tentang teknik."}, {"kind": "p", "text": "Bukti: Murid menunjukkan satu cara selamat ketika tangan, bahu dan sisi badan."}, {"kind": "p", "text": "Kriteria: Gerakan kecil atau tahan tanpa henjutan dikenal; tidak menarik rakan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Cara selamat ditunjukkan: ____"}, {"kind": "p", "text": "2. Bantuan / belum dilihat: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.2 — Jenis regangan; kod tercetak pertama"}, {"kind": "p", "text": "Kaedah: Soal jawab individu selepas bergerak."}, {"kind": "p", "text": "Bukti: Murid mengenal mana gerakan dinamik dan mana regangan statik yang telah dilakukan."}, {"kind": "p", "text": "Kriteria: Kedua-dua jenis dikenal melalui bergerak terkawal dan mengekalkan posisi. Ini pernyataan pertama berkod 4.3.2."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Dinamik dikenal: ____"}, {"kind": "p", "text": "2. Statik dikenal: ____"}, {"kind": "p", "text": "3. Bantuan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.3.2 — Tujuan regangan; kod tercetak kedua"}, {"kind": "p", "text": "Kaedah: Soalan tujuan dengan kata mudah."}, {"kind": "p", "text": "Bukti: Murid menyebut tujuan regangan bagi tangan, bahu dan sisi badan."}, {"kind": "p", "text": "Kriteria: Murid menyebut membantu kelenturan atau memudahkan gerakan. Ini pernyataan kedua berkod 4.3.2; bukan kod DSKP 4.3.3 yang direka."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Tujuan yang disebut: ____"}, {"kind": "p", "text": "2. Kata bantu / belum didengar: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.3"}, {"kind": "p", "text": "Kaedah: Pemerhatian dan respons individu sepanjang latihan."}, {"kind": "p", "text": "Bukti: Tindakan mula, berhenti dan menjaga ruang mengikut arahan."}, {"kind": "p", "text": "Kriteria: Arahan dipatuhi dengan bantuan; berhenti kerana sakit ialah tindakan selamat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Respons atau tindakan sebenar: ____"}, {"kind": "p", "text": "2. Bantuan / rehat / belum dilihat: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Jika condongan sisi tidak selesa, hentikan bahagian itu dan rekod belum dilaksanakan; guru menentukan penyesuaian seterusnya."}, {"kind": "p", "text": "2. Ulang jenis dan tujuan melalui dua soalan berasingan supaya rekod kod berulang tidak menghapuskan salah satu hasil."}]'::jsonb,'{"source_hold": "", "adaptation_note": "RPT menumpukan statik BT54–55; dinamik BT52–53 digunakan dalam sesi juga. Dua pernyataan 4.3.2 tercetak dikekalkan; nombor RPT4.3.3 ditanda konflik. Regangan lembut kiri/kanan tanpa henjutan, tarikan pasangan atau sasaran sakit. SP5.1.3 digunakan mengikut ayat rasmi DSKP, bukan gabungan ayat keselamatan lama RPT.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W37-S1','pj',1,2026,37,1,30,'3.4.1',array[56,57]::int[],'d14d46dfe4c88ab49f85bcea8c0673055a1625c8531d70dbcb78ea3db2d36113','5c33cba9f7504e1d0125b9cc2d9a10421a9b3c83406159e64ef84627fa133eb5','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W37-S1", "subject": "Pendidikan Jasmani", "year": 1, "week": 37, "session": 1, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Siapa Kuat?", "source_title": "Siapa Kuat?", "unit": "Unit 8: Cergas dan Mantap", "source_row_id": "PJ1-RPT2026-T13-R3", "source_row_literal": ["37\n\nKump A: 18.10.2026-22.10.2026\n\nKump B: 19.10.2026- 23.10.2026", "8: CERGAS DAN MANTAP\n\nSIAPA KUAT", ".\n3.4 Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul\n4.4 Mengaplikasi konsep asas kekuatan dan daya tahan otot.\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "3.4.1 Mengekalkan posisi sedia tekan tubi dalam suatu jangka masa. \n\n3.4.2 Mengekalkan posisi separa cangkung (half squat) dalam suatu jangka masa. \n\n3.4.3 Melakukan pergerakan dari duduk ke berdiri tanpa sokongan. \n\n3.4.4 Melakukan pergerakan dari baring ke duduk tanpa sokongan. \n\n3.4.5 Melakukan aktiviti bergayut dan meniti pada palang menggunakan tangan. \n\n3.4.6 Melakukan ringkuk tubi separa.\n \n4.4.1 Menyatakan kelebihan mempunyai otot yang kuat. \n\n4.4.2 Menyatakan kelebihan mempunyai otot yang boleh bekerja berulang-ulang dalam satu jangka masa. \n\n4.4.3 Mengenal pasti otot utama pada bahagian badan semasa melakukan senaman daya tahan otot \n\n5.1.4 Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani", "Pemerhatian /\nPentaksiran\n\n\nBT m/s 56-57"], "rpt_original_page_literal": "56-57", "source_pages": [56, 57], "source_pdf_pages": [64, 65], "rpt_book_pages": "56, 57", "main_standard_key": "3.4.1", "sk_code": "3.4", "sk_text": "Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul.", "sp_code": "3.4.1", "sp_text": "Mengekalkan posisi sedia tekan tubi dalam suatu jangka masa.", "complementary_standards": [{"standard_key": "3.4.2", "sp_code": "3.4.2", "sp_text": "Mengekalkan posisi separa cangkung (half squat) dalam suatu jangka masa.", "sk_code": "3.4", "sk_text": "Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul.", "domain": "psikomotor", "source_label": ""}, {"standard_key": "3.4.3", "sp_code": "3.4.3", "sp_text": "Melakukan pergerakan dari duduk ke berdiri tanpa sokongan.", "sk_code": "3.4", "sk_text": "Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul.", "domain": "psikomotor", "source_label": ""}, {"standard_key": "4.4.1", "sp_code": "4.4.1", "sp_text": "Menyatakan kelebihan mempunyai otot yang kuat.", "sk_code": "4.4", "sk_text": "Mengaplikasi konsep asas kekuatan dan daya tahan otot.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.4.3", "sp_code": "4.4.3", "sp_text": "Mengenal pasti otot utama pada bahagian badan semasa melakukan senaman daya tahan otot.", "sk_code": "4.4", "sk_text": "Mengaplikasi konsep asas kekuatan dan daya tahan otot.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.4", "sp_code": "5.1.4", "sp_text": "Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "source_task": "Menahan posisi dan bangun daripada duduk", "authoring_focus": "Menahan posisi dan bangun daripada duduk", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": true, "facility_replacement_note": "SP3.4.5 bergayut/meniti belum dilaksanakan kerana tiada palang sesuai.", "source_subset_focus": true, "source_subset_note": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap.", "adaptation_note": "Tiada palang sesuai. SP3.4.5 bergayut/meniti belum dilaksanakan dan tiada alatan rumah dijadikan pengganti. S1 melatih posisi sedia tekan tubi, separa cangkung serta duduk ke berdiri; S2 ringkuk tubi separa serta baring ke duduk. Tempoh pendek dan bantuan ikut kemampuan; bantuan tidak dianggap lakuan tanpa sokongan.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [{"standard_key": "3.4.5", "sp_code": "3.4.5", "sp_text": "Melakukan aktiviti bergayut dan meniti pada palang menggunakan tangan.", "sk_code": "3.4", "sk_text": "Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul.", "status": "NOT_PERFORMED_NO_SAFE_BAR", "reason": "Tiada palang sesuai; tidak diganti dengan perabot atau bingkai pintu."}], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": ["3.4.5: Tiada palang sesuai; tidak diganti dengan perabot atau bingkai pintu."], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Tiada palang sesuai. Aktiviti bergayut dan meniti SP3.4.5 belum dilaksanakan; jangan menggunakan meja, kerusi, pintu atau palang sementara.", "Latihan mengikut kemampuan, bukan pertandingan masa atau ulangan. Bernafas seperti biasa; berhenti jika sakit, pening atau sukar bernafas.", "Murid tidak memegang kaki, menarik tangan atau menekan tubuh rakan. Bantuan mengubah tahap lakuan dan mesti dicatat.", "Guru menunjukkan postur dengan jelas. Jika bentuk tidak dapat dikekalkan, lepaskan posisi dan rehat; jangan memaksa tahan sehingga menggigil atau sakit."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Tahan posisi sedia dan bangun daripada duduk", "objective": "Murid dapat melakukan latihan kekuatan otot dengan postur yang selamat mengikut kemampuan.", "success_criteria": ["Mencuba posisi sedia tekan tubi, separa cangkung dan duduk ke berdiri; lakuan serta bantuan dicatat berasingan.", "Menyebut satu kelebihan otot kuat dan otot utama bagi latihan yang dilakukan."], "prior_knowledge": "Murid pernah melakukan gerakan lutut kecil dan menggunakan tilam dengan giliran.", "equipment": [{"item": "Tilam atau alas senaman rata", "quantity": "Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak.", "use": "Seorang berlatih sementara pasangan menunggu di sisi tanpa menyokong tubuh."}, {"item": "Kon penanda", "quantity": "Empat kon di luar tilam dan ruang pijakan.", "use": "Menandakan ruang latihan serta rehat."}, {"item": "Jam guru dan air minuman sendiri", "quantity": "Satu jam guru; botol sendiri mengikut keperluan.", "use": "Masa tahan pendek, rehat dan pertukaran giliran."}], "preparation": ["Guru memeriksa tilam dan menyediakan ruang yang cukup untuk tubuh lurus tanpa terkena rakan.", "Sediakan tiga contoh: posisi sedia tekan tubi, separa cangkung serta duduk ke berdiri. Tiada palang atau ganti palang disediakan.", "Tentukan pasangan A dan B. Catat pengubahsuaian seperti lutut di alas atau bantuan tangan; jangan menyamakan dengan lakuan tanpa sokongan."], "organisation": ["Seorang menggunakan ruang latihan dan seorang menunggu di sisi. Kedua-duanya mendapat tiga aktiviti sendiri.", "Guru memimpin secara berturutan, bukan membuka tiga stesen berisiko serentak. Semua berhenti jika guru perlu bantuan dekat.", "Cadangan satu tahan 10 saat, rehat sekurang-kurangnya 20 saat sebelum ulangan. Boleh tamat lebih awal; tiada ulang paksa."], "movement_cues": ["Posisi sedia tekan tubi: tapak tangan di bawah bahu, lengan lurus selesa dan badan memanjang dengan sokongan hujung kaki. Pandang alas, jangan dongak atau biarkan pinggang melendut.", "Jika belum mampu, turunkan lutut ke alas sebagai ansur maju. Catat penyesuaian lutut, bukan mendakwa posisi penuh.", "Separa cangkung: kaki selesa selebar bahu, bengkokkan lutut sedikit dengan tapak kaki kekal di lantai, kemudian tahan selesa dan berdiri perlahan.", "Duduk ke berdiri: dari duduk selesa di tilam, bengkokkan lutut, letak kaki stabil dan alih badan ke depan untuk bangun. Cuba tanpa menolak lantai atau diangkat rakan hanya jika mampu; gunakan tangan apabila perlu dan catat bantuan.", "Posisi tekan tubi melibatkan lengan dan bahu; separa cangkung serta duduk ke berdiri melibatkan kaki dan pinggul. Otot kuat membantu pergerakan harian seperti bangun dan membawa barang ringan."], "timing_note": "Rujukan BT56–57 menyebut 10–15 saat. Sesi menggunakan cadangan 10 saat dan rehat; tempoh sebenar lebih pendek serta sokongan direkod. Semua dalam 30 minit.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Tahan setakat mampu. Jika pinggang mula melendut atau sakit, turunkan lutut dan rehat.", "pupils_do": "Murid menghentikan posisi dengan selamat dan memaklumkan guru.", "teacher_checks": "Guru merekod lakuan penuh atau ansur maju tanpa memaksa tahan."}, "bbm": ["Tilam atau alas senaman rata — Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak.", "Kon penanda — Empat kon di luar tilam dan ruang pijakan.", "Jam guru dan air minuman sendiri — Satu jam guru; botol sendiri mengikut keperluan.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Tilam atau alas senaman rata", "Kon penanda", "Jam guru dan air minuman sendiri"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Tiga lakuan dan otot yang digunakan", "minutes": 4, "teacher": ["Guru menunjukkan posisi sedia, separa cangkung dan duduk ke berdiri sekali.", "Guru menamakan lengan/bahu bagi posisi sedia serta kaki/pinggul bagi dua lakuan lain. Tunjukkan cara melepaskan posisi."], "pupils": ["Murid melihat postur dan mencuba posisi awal yang ringan.", "Murid menunjuk bahagian lengan atau kaki sendiri di atas pakaian apabila ditanya, tanpa menyentuh rakan."], "check": "Murid mengenal tindakan dan rehat yang selamat.", "resources": ["Tilam", "Jam"]}, {"name": "Tahan dengan rehat", "minutes": 9, "teacher": ["Gunakan satu minit menyemak posisi awal semua pasangan.", "Beri tiga minit kepada A dan tiga minit kepada B untuk posisi sedia dan separa cangkung: tahan sekitar 10 saat jika mampu, rehat sekurang-kurangnya 20 saat dan ulang sekali jika selesa.", "Gunakan dua minit akhir untuk rehat/minum dan percubaan duduk ke berdiri yang dipimpin guru."], "pupils": ["Murid melakukan dua posisi pada gilirannya dan melepaskan perlahan.", "Murid menggunakan penyesuaian yang guru benarkan jika perlu serta memberitahu rasa sakit.", "Murid mencuba bangun dari duduk tanpa sokongan jika bersedia; jika menggunakan tangan, biarkan guru mencatat lakuan sebenar."], "check": "Tiga kemahiran direkod berasingan; tangan atau lutut membantu tidak disembunyikan.", "resources": ["Tilam", "Jam", "Air sendiri"]}, {"name": "Giliran bangun dan semak postur", "minutes": 7, "teacher": ["Beri dua minit setiap giliran A dan B untuk satu atau dua percubaan duduk ke berdiri serta semakan satu posisi tahan yang perlu.", "Beri satu minit rehat dan dua minit soal jawab kelebihan otot kuat serta otot utama.", "Jangan meminta murid memegang atau mengangkat pasangannya. Rekod bahagian belum diperhatikan."], "pupils": ["Murid menjalani giliran sendiri dengan kaki stabil.", "Murid menyebut satu kelebihan otot kuat serta menamakan lengan/bahu bagi posisi sedia dan kaki/pinggul bagi cangkung serta bangun.", "Murid menunggu di sisi dan mengikut arahan berhenti."], "check": "Pemerhatian individu, bantuan dan bahagian yang masih tertangguh dinyatakan.", "resources": ["Tilam", "Jam"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Mencuba tiga lakuan dengan contoh guru dan sokongan yang dicatat.", "materials": ["Tilam rata"], "teacher": ["Guru mengajar posisi awal satu demi satu; benarkan lutut di alas atau bantuan tangan.", "Jangan menuntut lakuan tanpa sokongan jika murid belum bersedia."], "pupil_steps": ["Cuba posisi sedia tekan tubi; turunkan lutut jika perlu dan rehat.", "Cuba separa cangkung cetek dengan tahan yang selesa.", "Cuba duduk ke berdiri, menggunakan tangan jika perlu dengan bantuan dicatat.", "Sebut otot lengan/bahu bagi posisi sedia dan kaki/pinggul bagi cangkung serta bangun; nyatakan satu kelebihan otot kuat."], "product": "Tiga percubaan individu dengan status penuh atau ansur maju.", "criterion": "Ketiga-tiga percubaan dijejak; bantuan bukan bukti tanpa sokongan.", "next_step": "Ulang posisi awal yang selesa pada giliran lain.", "example": {"teacher": "Otot kuat membantu kita buat apa?", "pupil": "Membantu kita bangun dan bergerak."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Melakukan tiga lakuan dengan kawalan dan rehat.", "materials": ["Tilam", "Jam guru"], "teacher": ["Semak bahu serta pinggang sebelum tahan.", "Bantu memilih posisi kaki ketika bangun tanpa menarik tangan murid."], "pupil_steps": ["Lakukan posisi sedia tekan tubi dan lepaskan selepas tempoh yang mampu.", "Tahan separa cangkung pendek, kemudian rehat.", "Bangun daripada duduk hingga berdiri tanpa sokongan jika mampu; guru mencatat jika tangan digunakan.", "Namakan otot lengan/bahu serta kaki/pinggul dan satu kelebihan otot kuat."], "product": "Tiga lakuan sendiri dan penerangan otot.", "criterion": "Postur selamat, bantuan dicatat dan tempoh tidak dipaksa.", "next_step": "Perkemas satu posisi tanpa menambah masa tahan.", "example": {"teacher": "Otot apa membantu separa cangkung?", "pupil": "Otot kaki dan pinggul."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas pelepasan posisi dan bangun yang stabil.", "materials": ["Tilam rata"], "teacher": ["Minta satu pembaikan seperti pinggang tidak melendut.", "Jangan tambah beban, ulangan atau masa."], "pupil_steps": ["Tahan posisi sedia tekan tubi dalam julat mampu.", "Lakukan separa cangkung dan lepaskan perlahan.", "Bangun dari duduk hingga berdiri dengan terkawal tanpa sokongan jika mampu.", "Terangkan satu kelebihan otot kuat dan otot utama bagi tiga lakuan."], "product": "Tiga lakuan dengan pembaikan kawalan dan respons sendiri.", "criterion": "Kawalan diperbaik tanpa mengubah bantuan menjadi syarat lulus.", "next_step": "Kekalkan postur yang selesa dan rehat mencukupi.", "example": {"teacher": "Bagaimana kamu memperkemas lakuan?", "pupil": "Saya lepaskan posisi perlahan dan bangun dengan kaki stabil."}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan latihan kekuatan otot dengan postur yang selamat mengikut kemampuan.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bimbing ansur maju Peneroka.", "Semak tiga lakuan Pembina.", "Perkemas pelepasan Pencabar tanpa menaikkan usaha."], "individual_check": "Mencuba posisi sedia tekan tubi, separa cangkung dan duduk ke berdiri; lakuan serta bantuan dicatat berasingan.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian dekat posisi sedia.", "evidence": "Tahanan posisi sedia tekan tubi serta tempoh sebenar.", "criterion": "Posisi selamat dikekalkan setakat mampu; lutut di alas dicatat sebagai ansur maju.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Posisi penuh / lutut di alas: ____", "Tempoh sebenar: ____", "Bantuan / belum diperhatikan: ____"]}, "pbd_complementary": {"3.4.2": {"method": "Pemerhatian separa cangkung.", "evidence": "Kedudukan lutut, kaki dan tahan murid sendiri.", "criterion": "Separa cangkung selesa tanpa sakit atau tapak kaki terangkat; tempoh sebenar dicatat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Postur: ____", "Tempoh: ____", "Bantuan / tertangguh: ____"]}, "3.4.3": {"method": "Pemerhatian percubaan duduk ke berdiri.", "evidence": "Murid bangun sendiri serta penggunaan tangan atau bantuan.", "criterion": "Lakuan tanpa sokongan hanya dicatat apabila benar-benar tanpa menolak lantai atau bantuan orang.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Percubaan sebenar: ____", "Tanpa sokongan / dengan tangan: ____", "Belum bersedia / susulan: ____"]}, "4.4.1": {"method": "Soal jawab individu selepas rehat.", "evidence": "Satu kelebihan otot kuat yang disebut murid.", "criterion": "Menyebut membantu bangun, bergerak atau membawa barang ringan; tiada ujian beban.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Jawapan: ____", "Bantuan: ____"]}, "4.4.3": {"method": "Soalan otot mengikut aktiviti.", "evidence": "Lengan/bahu bagi posisi sedia dan kaki/pinggul bagi separa cangkung serta bangun.", "criterion": "Murid mengenal bahagian otot utama melalui kata mudah.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Lengan/bahu: ____", "Kaki/pinggul: ____", "Bantuan: ____"]}, "5.1.4": {"method": "Pemerhatian aturan tilam dan rehat.", "evidence": "Giliran, tempat menunggu dan berhenti apabila perlu.", "criterion": "Murid mematuhi peraturan tanpa membantu tubuh rakan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Giliran selamat: ____", "Berhenti/rehat: ____", "Belum diperhatikan: ____"]}}, "intervention": ["Bagi murid yang perlu tangan untuk bangun, terima bantuan dan teruskan ansur maju; jangan merekod tanpa sokongan.", "Baki giliran disusuli. SP3.4.5 kekal belum dilaksanakan kerana tiada palang sesuai."], "book_pages_text": "56, 57", "sp_focus": "", "sp_display": "3.4.1", "complementary": [{"standard_key": "3.4.2", "sp_code": "3.4.2", "sp_text": "Mengekalkan posisi separa cangkung (half squat) dalam suatu jangka masa.", "sk_code": "3.4", "sk_text": "Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul.", "domain": "psikomotor", "source_label": ""}, {"standard_key": "3.4.3", "sp_code": "3.4.3", "sp_text": "Melakukan pergerakan dari duduk ke berdiri tanpa sokongan.", "sk_code": "3.4", "sk_text": "Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul.", "domain": "psikomotor", "source_label": ""}, {"standard_key": "4.4.1", "sp_code": "4.4.1", "sp_text": "Menyatakan kelebihan mempunyai otot yang kuat.", "sk_code": "4.4", "sk_text": "Mengaplikasi konsep asas kekuatan dan daya tahan otot.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.4.3", "sp_code": "4.4.3", "sp_text": "Mengenal pasti otot utama pada bahagian badan semasa melakukan senaman daya tahan otot.", "sk_code": "4.4", "sk_text": "Mengaplikasi konsep asas kekuatan dan daya tahan otot.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.4", "sp_code": "5.1.4", "sp_text": "Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "draft_sha256": "ee8ce540e345a8c1d821516df0b1fd30b0b78b52dc0c7e1d47d1f908d2de9481"}'::jsonb,'[{"kind": "title", "text": "Minggu 37 Sesi 1 — Tahan posisi sedia dan bangun daripada duduk"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W37-S1"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 8: Cergas dan Mantap"}, {"kind": "p", "text": "Tajuk buku teks: Siapa Kuat?"}, {"kind": "p", "text": "Aktiviti guru: Tahan posisi sedia dan bangun daripada duduk"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 56, 57."}, {"kind": "p", "text": "Rujukan BT56–57 menyebut 10–15 saat. Sesi menggunakan cadangan 10 saat dan rehat; tempoh sebenar lebih pendek serta sokongan direkod. Semua dalam 30 minit."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.4: Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul."}, {"kind": "p", "text": "SP utama 3.4.1: Mengekalkan posisi sedia tekan tubi dalam suatu jangka masa."}, {"kind": "p", "text": "SK sokongan 3.4: Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul."}, {"kind": "p", "text": "SP sokongan 3.4.2: Mengekalkan posisi separa cangkung (half squat) dalam suatu jangka masa."}, {"kind": "p", "text": "SK sokongan 3.4: Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul."}, {"kind": "p", "text": "SP sokongan 3.4.3: Melakukan pergerakan dari duduk ke berdiri tanpa sokongan."}, {"kind": "p", "text": "SK sokongan 4.4: Mengaplikasi konsep asas kekuatan dan daya tahan otot."}, {"kind": "p", "text": "SP sokongan 4.4.1: Menyatakan kelebihan mempunyai otot yang kuat."}, {"kind": "p", "text": "SK sokongan 4.4: Mengaplikasi konsep asas kekuatan dan daya tahan otot."}, {"kind": "p", "text": "SP sokongan 4.4.3: Mengenal pasti otot utama pada bahagian badan semasa melakukan senaman daya tahan otot."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.4: Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "SP3.4.5 bergayut/meniti belum dilaksanakan kerana tiada palang sesuai."}, {"kind": "p", "text": "SP sumber yang belum dilaksanakan atau belum lengkap: 3.4.5 — Melakukan aktiviti bergayut dan meniti pada palang menggunakan tangan. Tiada palang sesuai; tidak diganti dengan perabot atau bingkai pintu."}, {"kind": "p", "text": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan latihan kekuatan otot dengan postur yang selamat mengikut kemampuan."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Mencuba posisi sedia tekan tubi, separa cangkung dan duduk ke berdiri; lakuan serta bantuan dicatat berasingan."}, {"kind": "p", "text": "2. Menyebut satu kelebihan otot kuat dan otot utama bagi latihan yang dilakukan."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah melakukan gerakan lutut kecil dan menggunakan tilam dengan giliran."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Tilam atau alas senaman rata"}, {"kind": "p", "text": "Keperluan: Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak."}, {"kind": "p", "text": "Kegunaan: Seorang berlatih sementara pasangan menunggu di sisi tanpa menyokong tubuh."}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: Empat kon di luar tilam dan ruang pijakan."}, {"kind": "p", "text": "Kegunaan: Menandakan ruang latihan serta rehat."}, {"kind": "label", "text": "Jam guru dan air minuman sendiri"}, {"kind": "p", "text": "Keperluan: Satu jam guru; botol sendiri mengikut keperluan."}, {"kind": "p", "text": "Kegunaan: Masa tahan pendek, rehat dan pertukaran giliran."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Guru memeriksa tilam dan menyediakan ruang yang cukup untuk tubuh lurus tanpa terkena rakan."}, {"kind": "p", "text": "2. Sediakan tiga contoh: posisi sedia tekan tubi, separa cangkung serta duduk ke berdiri. Tiada palang atau ganti palang disediakan."}, {"kind": "p", "text": "3. Tentukan pasangan A dan B. Catat pengubahsuaian seperti lutut di alas atau bantuan tangan; jangan menyamakan dengan lakuan tanpa sokongan."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Seorang menggunakan ruang latihan dan seorang menunggu di sisi. Kedua-duanya mendapat tiga aktiviti sendiri."}, {"kind": "p", "text": "2. Guru memimpin secara berturutan, bukan membuka tiga stesen berisiko serentak. Semua berhenti jika guru perlu bantuan dekat."}, {"kind": "p", "text": "3. Cadangan satu tahan 10 saat, rehat sekurang-kurangnya 20 saat sebelum ulangan. Boleh tamat lebih awal; tiada ulang paksa."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Posisi sedia tekan tubi: tapak tangan di bawah bahu, lengan lurus selesa dan badan memanjang dengan sokongan hujung kaki. Pandang alas, jangan dongak atau biarkan pinggang melendut."}, {"kind": "p", "text": "2. Jika belum mampu, turunkan lutut ke alas sebagai ansur maju. Catat penyesuaian lutut, bukan mendakwa posisi penuh."}, {"kind": "p", "text": "3. Separa cangkung: kaki selesa selebar bahu, bengkokkan lutut sedikit dengan tapak kaki kekal di lantai, kemudian tahan selesa dan berdiri perlahan."}, {"kind": "p", "text": "4. Duduk ke berdiri: dari duduk selesa di tilam, bengkokkan lutut, letak kaki stabil dan alih badan ke depan untuk bangun. Cuba tanpa menolak lantai atau diangkat rakan hanya jika mampu; gunakan tangan apabila perlu dan catat bantuan."}, {"kind": "p", "text": "5. Posisi tekan tubi melibatkan lengan dan bahu; separa cangkung serta duduk ke berdiri melibatkan kaki dan pinggul. Otot kuat membantu pergerakan harian seperti bangun dan membawa barang ringan."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Tilam atau alas senaman rata — Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak."}, {"kind": "p", "text": "2. Kon penanda — Empat kon di luar tilam dan ruang pijakan."}, {"kind": "p", "text": "3. Jam guru dan air minuman sendiri — Satu jam guru; botol sendiri mengikut keperluan."}, {"kind": "p", "text": "4. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Tiada palang sesuai. Aktiviti bergayut dan meniti SP3.4.5 belum dilaksanakan; jangan menggunakan meja, kerusi, pintu atau palang sementara."}, {"kind": "p", "text": "5. Latihan mengikut kemampuan, bukan pertandingan masa atau ulangan. Bernafas seperti biasa; berhenti jika sakit, pening atau sukar bernafas."}, {"kind": "p", "text": "6. Murid tidak memegang kaki, menarik tangan atau menekan tubuh rakan. Bantuan mengubah tahap lakuan dan mesti dicatat."}, {"kind": "p", "text": "7. Guru menunjukkan postur dengan jelas. Jika bentuk tidak dapat dikekalkan, lepaskan posisi dan rehat; jangan memaksa tahan sehingga menggigil atau sakit."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Tilam atau alas senaman rata Kon penanda Jam guru dan air minuman sendiri"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Tiga lakuan dan otot yang digunakan — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan posisi sedia, separa cangkung dan duduk ke berdiri sekali."}, {"kind": "p", "text": "2. Guru menamakan lengan/bahu bagi posisi sedia serta kaki/pinggul bagi dua lakuan lain. Tunjukkan cara melepaskan posisi."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid melihat postur dan mencuba posisi awal yang ringan."}, {"kind": "p", "text": "2. Murid menunjuk bahagian lengan atau kaki sendiri di atas pakaian apabila ditanya, tanpa menyentuh rakan."}, {"kind": "p", "text": "Semakan: Murid mengenal tindakan dan rehat yang selamat."}, {"kind": "p", "text": "Alatan: Tilam Jam"}, {"kind": "h3", "text": "Langkah 4: Tahan dengan rehat — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Gunakan satu minit menyemak posisi awal semua pasangan."}, {"kind": "p", "text": "2. Beri tiga minit kepada A dan tiga minit kepada B untuk posisi sedia dan separa cangkung: tahan sekitar 10 saat jika mampu, rehat sekurang-kurangnya 20 saat dan ulang sekali jika selesa."}, {"kind": "p", "text": "3. Gunakan dua minit akhir untuk rehat/minum dan percubaan duduk ke berdiri yang dipimpin guru."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid melakukan dua posisi pada gilirannya dan melepaskan perlahan."}, {"kind": "p", "text": "2. Murid menggunakan penyesuaian yang guru benarkan jika perlu serta memberitahu rasa sakit."}, {"kind": "p", "text": "3. Murid mencuba bangun dari duduk tanpa sokongan jika bersedia; jika menggunakan tangan, biarkan guru mencatat lakuan sebenar."}, {"kind": "p", "text": "Semakan: Tiga kemahiran direkod berasingan; tangan atau lutut membantu tidak disembunyikan."}, {"kind": "p", "text": "Alatan: Tilam Jam Air sendiri"}, {"kind": "h3", "text": "Langkah 5: Giliran bangun dan semak postur — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Beri dua minit setiap giliran A dan B untuk satu atau dua percubaan duduk ke berdiri serta semakan satu posisi tahan yang perlu."}, {"kind": "p", "text": "2. Beri satu minit rehat dan dua minit soal jawab kelebihan otot kuat serta otot utama."}, {"kind": "p", "text": "3. Jangan meminta murid memegang atau mengangkat pasangannya. Rekod bahagian belum diperhatikan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menjalani giliran sendiri dengan kaki stabil."}, {"kind": "p", "text": "2. Murid menyebut satu kelebihan otot kuat serta menamakan lengan/bahu bagi posisi sedia dan kaki/pinggul bagi cangkung serta bangun."}, {"kind": "p", "text": "3. Murid menunggu di sisi dan mengikut arahan berhenti."}, {"kind": "p", "text": "Semakan: Pemerhatian individu, bantuan dan bahagian yang masih tertangguh dinyatakan."}, {"kind": "p", "text": "Alatan: Tilam Jam"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Tahan setakat mampu. Jika pinggang mula melendut atau sakit, turunkan lutut dan rehat."}, {"kind": "p", "text": "Murid: Murid menghentikan posisi dengan selamat dan memaklumkan guru."}, {"kind": "p", "text": "Semakan guru: Guru merekod lakuan penuh atau ansur maju tanpa memaksa tahan."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W37-S1"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan latihan kekuatan otot dengan postur yang selamat mengikut kemampuan."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bimbing ansur maju Peneroka."}, {"kind": "p", "text": "2. Semak tiga lakuan Pembina."}, {"kind": "p", "text": "3. Perkemas pelepasan Pencabar tanpa menaikkan usaha."}, {"kind": "p", "text": "Semakan individu: Mencuba posisi sedia tekan tubi, separa cangkung dan duduk ke berdiri; lakuan serta bantuan dicatat berasingan."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Mencuba tiga lakuan dengan contoh guru dan sokongan yang dicatat."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam rata"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru mengajar posisi awal satu demi satu; benarkan lutut di alas atau bantuan tangan."}, {"kind": "p", "text": "2. Jangan menuntut lakuan tanpa sokongan jika murid belum bersedia."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Cuba posisi sedia tekan tubi; turunkan lutut jika perlu dan rehat."}, {"kind": "p", "text": "2. Cuba separa cangkung cetek dengan tahan yang selesa."}, {"kind": "p", "text": "3. Cuba duduk ke berdiri, menggunakan tangan jika perlu dengan bantuan dicatat."}, {"kind": "p", "text": "4. Sebut otot lengan/bahu bagi posisi sedia dan kaki/pinggul bagi cangkung serta bangun; nyatakan satu kelebihan otot kuat."}, {"kind": "p", "text": "Contoh guru: Otot kuat membantu kita buat apa?"}, {"kind": "p", "text": "Contoh respons murid: Membantu kita bangun dan bergerak."}, {"kind": "p", "text": "Hasil individu: Tiga percubaan individu dengan status penuh atau ansur maju."}, {"kind": "p", "text": "Kriteria: Ketiga-tiga percubaan dijejak; bantuan bukan bukti tanpa sokongan."}, {"kind": "p", "text": "Susulan: Ulang posisi awal yang selesa pada giliran lain."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Melakukan tiga lakuan dengan kawalan dan rehat."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam"}, {"kind": "p", "text": "2. Jam guru"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Semak bahu serta pinggang sebelum tahan."}, {"kind": "p", "text": "2. Bantu memilih posisi kaki ketika bangun tanpa menarik tangan murid."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Lakukan posisi sedia tekan tubi dan lepaskan selepas tempoh yang mampu."}, {"kind": "p", "text": "2. Tahan separa cangkung pendek, kemudian rehat."}, {"kind": "p", "text": "3. Bangun daripada duduk hingga berdiri tanpa sokongan jika mampu; guru mencatat jika tangan digunakan."}, {"kind": "p", "text": "4. Namakan otot lengan/bahu serta kaki/pinggul dan satu kelebihan otot kuat."}, {"kind": "p", "text": "Contoh guru: Otot apa membantu separa cangkung?"}, {"kind": "p", "text": "Contoh respons murid: Otot kaki dan pinggul."}, {"kind": "p", "text": "Hasil individu: Tiga lakuan sendiri dan penerangan otot."}, {"kind": "p", "text": "Kriteria: Postur selamat, bantuan dicatat dan tempoh tidak dipaksa."}, {"kind": "p", "text": "Susulan: Perkemas satu posisi tanpa menambah masa tahan."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas pelepasan posisi dan bangun yang stabil."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam rata"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minta satu pembaikan seperti pinggang tidak melendut."}, {"kind": "p", "text": "2. Jangan tambah beban, ulangan atau masa."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Tahan posisi sedia tekan tubi dalam julat mampu."}, {"kind": "p", "text": "2. Lakukan separa cangkung dan lepaskan perlahan."}, {"kind": "p", "text": "3. Bangun dari duduk hingga berdiri dengan terkawal tanpa sokongan jika mampu."}, {"kind": "p", "text": "4. Terangkan satu kelebihan otot kuat dan otot utama bagi tiga lakuan."}, {"kind": "p", "text": "Contoh guru: Bagaimana kamu memperkemas lakuan?"}, {"kind": "p", "text": "Contoh respons murid: Saya lepaskan posisi perlahan dan bangun dengan kaki stabil."}, {"kind": "p", "text": "Hasil individu: Tiga lakuan dengan pembaikan kawalan dan respons sendiri."}, {"kind": "p", "text": "Kriteria: Kawalan diperbaik tanpa mengubah bantuan menjadi syarat lulus."}, {"kind": "p", "text": "Susulan: Kekalkan postur yang selesa dan rehat mencukupi."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.4.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian dekat posisi sedia."}, {"kind": "p", "text": "Bukti: Tahanan posisi sedia tekan tubi serta tempoh sebenar."}, {"kind": "p", "text": "Kriteria: Posisi selamat dikekalkan setakat mampu; lutut di alas dicatat sebagai ansur maju."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Posisi penuh / lutut di alas: ____"}, {"kind": "p", "text": "2. Tempoh sebenar: ____"}, {"kind": "p", "text": "3. Bantuan / belum diperhatikan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 3.4.2"}, {"kind": "p", "text": "Kaedah: Pemerhatian separa cangkung."}, {"kind": "p", "text": "Bukti: Kedudukan lutut, kaki dan tahan murid sendiri."}, {"kind": "p", "text": "Kriteria: Separa cangkung selesa tanpa sakit atau tapak kaki terangkat; tempoh sebenar dicatat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Postur: ____"}, {"kind": "p", "text": "2. Tempoh: ____"}, {"kind": "p", "text": "3. Bantuan / tertangguh: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 3.4.3"}, {"kind": "p", "text": "Kaedah: Pemerhatian percubaan duduk ke berdiri."}, {"kind": "p", "text": "Bukti: Murid bangun sendiri serta penggunaan tangan atau bantuan."}, {"kind": "p", "text": "Kriteria: Lakuan tanpa sokongan hanya dicatat apabila benar-benar tanpa menolak lantai atau bantuan orang."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Percubaan sebenar: ____"}, {"kind": "p", "text": "2. Tanpa sokongan / dengan tangan: ____"}, {"kind": "p", "text": "3. Belum bersedia / susulan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.4.1"}, {"kind": "p", "text": "Kaedah: Soal jawab individu selepas rehat."}, {"kind": "p", "text": "Bukti: Satu kelebihan otot kuat yang disebut murid."}, {"kind": "p", "text": "Kriteria: Menyebut membantu bangun, bergerak atau membawa barang ringan; tiada ujian beban."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Jawapan: ____"}, {"kind": "p", "text": "2. Bantuan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.4.3"}, {"kind": "p", "text": "Kaedah: Soalan otot mengikut aktiviti."}, {"kind": "p", "text": "Bukti: Lengan/bahu bagi posisi sedia dan kaki/pinggul bagi separa cangkung serta bangun."}, {"kind": "p", "text": "Kriteria: Murid mengenal bahagian otot utama melalui kata mudah."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Lengan/bahu: ____"}, {"kind": "p", "text": "2. Kaki/pinggul: ____"}, {"kind": "p", "text": "3. Bantuan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.4"}, {"kind": "p", "text": "Kaedah: Pemerhatian aturan tilam dan rehat."}, {"kind": "p", "text": "Bukti: Giliran, tempat menunggu dan berhenti apabila perlu."}, {"kind": "p", "text": "Kriteria: Murid mematuhi peraturan tanpa membantu tubuh rakan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Giliran selamat: ____"}, {"kind": "p", "text": "2. Berhenti/rehat: ____"}, {"kind": "p", "text": "3. Belum diperhatikan: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Bagi murid yang perlu tangan untuk bangun, terima bantuan dan teruskan ansur maju; jangan merekod tanpa sokongan."}, {"kind": "p", "text": "2. Baki giliran disusuli. SP3.4.5 kekal belum dilaksanakan kerana tiada palang sesuai."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Tiada palang sesuai. SP3.4.5 bergayut/meniti belum dilaksanakan dan tiada alatan rumah dijadikan pengganti. S1 melatih posisi sedia tekan tubi, separa cangkung serta duduk ke berdiri; S2 ringkuk tubi separa serta baring ke duduk. Tempoh pendek dan bantuan ikut kemampuan; bantuan tidak dianggap lakuan tanpa sokongan.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W37-S2','pj',1,2026,37,2,30,'3.4.6',array[56,57]::int[],'374d574c4304b52789ad091fdc364f14eaa289d0144b1bd8ee615c69cbc065b2','84fbd3b3977ae3ef36de67d1f9f0521ddb995d912833b0d9181d5c69ba6ed530','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W37-S2", "subject": "Pendidikan Jasmani", "year": 1, "week": 37, "session": 2, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Siapa Kuat?", "source_title": "Siapa Kuat?", "unit": "Unit 8: Cergas dan Mantap", "source_row_id": "PJ1-RPT2026-T13-R3", "source_row_literal": ["37\n\nKump A: 18.10.2026-22.10.2026\n\nKump B: 19.10.2026- 23.10.2026", "8: CERGAS DAN MANTAP\n\nSIAPA KUAT", ".\n3.4 Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul\n4.4 Mengaplikasi konsep asas kekuatan dan daya tahan otot.\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "3.4.1 Mengekalkan posisi sedia tekan tubi dalam suatu jangka masa. \n\n3.4.2 Mengekalkan posisi separa cangkung (half squat) dalam suatu jangka masa. \n\n3.4.3 Melakukan pergerakan dari duduk ke berdiri tanpa sokongan. \n\n3.4.4 Melakukan pergerakan dari baring ke duduk tanpa sokongan. \n\n3.4.5 Melakukan aktiviti bergayut dan meniti pada palang menggunakan tangan. \n\n3.4.6 Melakukan ringkuk tubi separa.\n \n4.4.1 Menyatakan kelebihan mempunyai otot yang kuat. \n\n4.4.2 Menyatakan kelebihan mempunyai otot yang boleh bekerja berulang-ulang dalam satu jangka masa. \n\n4.4.3 Mengenal pasti otot utama pada bahagian badan semasa melakukan senaman daya tahan otot \n\n5.1.4 Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani", "Pemerhatian /\nPentaksiran\n\n\nBT m/s 56-57"], "rpt_original_page_literal": "56-57", "source_pages": [56, 57], "source_pdf_pages": [64, 65], "rpt_book_pages": "56, 57", "main_standard_key": "3.4.6", "sk_code": "3.4", "sk_text": "Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul.", "sp_code": "3.4.6", "sp_text": "Melakukan ringkuk tubi separa.", "complementary_standards": [{"standard_key": "3.4.4", "sp_code": "3.4.4", "sp_text": "Melakukan pergerakan dari baring ke duduk tanpa sokongan.", "sk_code": "3.4", "sk_text": "Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul.", "domain": "psikomotor", "source_label": ""}, {"standard_key": "4.4.2", "sp_code": "4.4.2", "sp_text": "Menyatakan kelebihan mempunyai otot yang boleh bekerja berulang-ulang dalam satu jangka masa.", "sk_code": "4.4", "sk_text": "Mengaplikasi konsep asas kekuatan dan daya tahan otot.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.4.3", "sp_code": "4.4.3", "sp_text": "Mengenal pasti otot utama pada bahagian badan semasa melakukan senaman daya tahan otot.", "sk_code": "4.4", "sk_text": "Mengaplikasi konsep asas kekuatan dan daya tahan otot.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.4", "sp_code": "5.1.4", "sp_text": "Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "source_task": "Ringkuk tubi separa dan baring ke duduk", "authoring_focus": "Ringkuk tubi separa dan baring ke duduk", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": true, "facility_replacement_note": "SP3.4.5 bergayut/meniti belum dilaksanakan kerana tiada palang sesuai.", "source_subset_focus": true, "source_subset_note": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap.", "adaptation_note": "Tiada palang sesuai. SP3.4.5 bergayut/meniti belum dilaksanakan dan tiada alatan rumah dijadikan pengganti. S1 melatih posisi sedia tekan tubi, separa cangkung serta duduk ke berdiri; S2 ringkuk tubi separa serta baring ke duduk. Tempoh pendek dan bantuan ikut kemampuan; bantuan tidak dianggap lakuan tanpa sokongan.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [{"standard_key": "3.4.5", "sp_code": "3.4.5", "sp_text": "Melakukan aktiviti bergayut dan meniti pada palang menggunakan tangan.", "sk_code": "3.4", "sk_text": "Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul.", "status": "NOT_PERFORMED_NO_SAFE_BAR", "reason": "Tiada palang sesuai; tidak diganti dengan perabot atau bingkai pintu."}], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": ["3.4.5: Tiada palang sesuai; tidak diganti dengan perabot atau bingkai pintu."], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Tiada palang sesuai. Aktiviti bergayut dan meniti SP3.4.5 belum dilaksanakan; jangan menggunakan meja, kerusi, pintu atau palang sementara.", "Latihan mengikut kemampuan, bukan pertandingan masa atau ulangan. Bernafas seperti biasa; berhenti jika sakit, pening atau sukar bernafas.", "Murid tidak memegang kaki, menarik tangan atau menekan tubuh rakan. Bantuan mengubah tahap lakuan dan mesti dicatat.", "Guru menunjukkan postur dengan jelas. Jika bentuk tidak dapat dikekalkan, lepaskan posisi dan rehat; jangan memaksa tahan sehingga menggigil atau sakit.", "Jangan merapatkan siku ke lutut secara paksa, menarik kepala dengan tangan atau meletakkan beban pada perut. Sakit belakang atau leher memerlukan berhenti dan perhatian guru."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Ringkuk tubi separa dan baring ke duduk", "objective": "Murid dapat melakukan latihan otot abdomen dengan gerakan yang terkawal mengikut kemampuan.", "success_criteria": ["Mencuba ringkuk tubi separa dan pergerakan baring ke duduk; bantuan serta perbezaan lakuan dicatat.", "Menyebut kelebihan otot yang boleh bekerja berulang-ulang dan mengenal otot abdomen."], "prior_knowledge": "Murid tahu menggunakan tilam, menjaga jarak dan berehat apabila perlu.", "equipment": [{"item": "Tilam atau alas senaman rata", "quantity": "Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak.", "use": "Seorang berlatih sementara pasangan menunggu di sisi tanpa menyokong tubuh."}, {"item": "Kon penanda", "quantity": "Empat kon di luar tilam dan ruang pijakan.", "use": "Menandakan ruang latihan serta rehat."}, {"item": "Jam guru dan air minuman sendiri", "quantity": "Satu jam guru; botol sendiri mengikut keperluan.", "use": "Masa tahan pendek, rehat dan pertukaran giliran."}], "preparation": ["Guru memeriksa alas rata dan menyediakan satu ruang selamat setiap pasangan.", "Tunjukkan perbezaan ringkuk separa dengan baring ke duduk sebelum menilai. Jangan menggunakan nama kedua-duanya untuk lakuan yang sama.", "Guru memilih murid yang bersedia untuk percubaan baring ke duduk. Bantuan tangan dibenarkan sebagai ansur maju dan direkod, bukan dianggap tanpa sokongan."], "organisation": ["A menggunakan alas sementara B menunggu di sisi; kemudian bertukar. Tiada pasangan memegang kaki atau menarik tangan.", "Setiap murid mencuba kedua-dua lakuan mengikut kesediaan. Guru menghentikan kelas jika perlu memberikan bantuan dekat.", "Cadangan dua atau tiga ulangan ringkuk dalam tempoh sehingga 10 saat, kemudian rehat sekurang-kurangnya 20 saat. Jangan berlumba menghabiskan ulangan."], "movement_cues": ["Ringkuk tubi separa: baring terlentang, lutut dibengkokkan selesa dan tapak kaki di alas. Tangan di paha atau di sisi; angkat bahu sedikit sambil menggelongsorkan tangan ke arah lutut, kemudian turun perlahan.", "Kepala seiring badan; jangan menarik leher atau menolak dagu kuat. Bernafas seperti biasa sepanjang pergerakan.", "Baring ke duduk: daripada baring dengan lutut selesa, cuba naik ke duduk secara terkawal tanpa ditarik rakan. Hanya murid bersedia mencuba tanpa tangan menolak alas; jika tangan diperlukan, catat sebagai bantuan.", "Ringkuk separa hanya mengangkat bahu sedikit, manakala baring ke duduk berakhir dalam duduk. Jangan memaksa murid menyiapkan lakuan penuh.", "Otot abdomen di bahagian perut membantu pergerakan ini. Daya tahan otot membolehkan otot bekerja berulang-ulang dalam tempoh tertentu, contohnya bangun atau bergerak beberapa kali tanpa cepat letih."], "timing_note": "Cadangan set singkat sehingga 10 saat dalam rujukan 10–15 saat buku, dengan rehat antara percubaan. Boleh lebih pendek; masa sebenar dan bantuan dicatat. Semua termasuk 30 minit.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Angkat bahu sedikit sahaja untuk ringkuk separa. Baring ke duduk ialah lakuan lain; jangan paksa jika belum mampu.", "pupils_do": "Murid melakukan lakuan yang dibenarkan dan turun perlahan tanpa rakan memegang kaki.", "teacher_checks": "Guru membezakan dua bukti dan merekod bantuan tangan serta tempoh sebenar."}, "bbm": ["Tilam atau alas senaman rata — Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak.", "Kon penanda — Empat kon di luar tilam dan ruang pijakan.", "Jam guru dan air minuman sendiri — Satu jam guru; botol sendiri mengikut keperluan.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Tilam atau alas senaman rata", "Kon penanda", "Jam guru dan air minuman sendiri"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Bezakan dua lakuan", "minutes": 4, "teacher": ["Guru menunjukkan ringkuk separa dengan lutut selesa dan bahu terangkat sedikit.", "Guru menunjukkan baring ke duduk sebagai lakuan berbeza serta cara berhenti jika belum bersedia.", "Guru menamakan abdomen dan menjelaskan daya tahan melalui kata bekerja berulang-ulang."], "pupils": ["Murid melihat perbezaan penamat dua lakuan.", "Murid menyebut ringkuk separa atau duduk apabila ditanya."], "check": "Murid tidak menyamakan separa dengan lakuan duduk penuh.", "resources": ["Tilam"]}, {"name": "Ringkuk separa dengan rehat", "minutes": 9, "teacher": ["Gunakan satu minit untuk posisi awal. Beri tiga minit kepada A dan tiga minit kepada B untuk ringkuk separa dalam set pendek, diselang rehat.", "Guru membimbing dua atau tiga ulangan perlahan jika mampu; jangan mengejar jumlah.", "Gunakan dua minit akhir untuk rehat/minum serta percubaan awal baring ke duduk yang dipantau guru."], "pupils": ["Murid baring dengan lutut dibengkokkan dan kaki stabil.", "Murid mengangkat bahu sedikit, turun perlahan dan berehat antara set.", "Murid mencuba baring ke duduk jika guru membenarkan; bantuan tangan tidak disembunyikan."], "check": "Kawalan ringkuk dan percubaan duduk diperhatikan berasingan.", "resources": ["Tilam", "Jam", "Air sendiri"]}, {"name": "Giliran baring ke duduk", "minutes": 7, "teacher": ["Beri dua minit setiap giliran A dan B untuk percubaan baring ke duduk dan satu pembetulan ringkuk yang perlu.", "Beri satu minit rehat dan dua minit soal jawab tentang abdomen serta kelebihan otot bekerja berulang-ulang.", "Catat belum bersedia jika lakuan penuh tidak dilakukan; jangan menarik tangan murid untuk melengkapkannya."], "pupils": ["Murid melakukan percubaan sendiri tanpa pasangan memegang kaki.", "Murid menyebut abdomen atau otot perut serta satu kelebihan daya tahan.", "Murid menunggu di sisi dan berhenti apabila diarahkan."], "check": "Bukti tanpa sokongan hanya diberi pada lakuan sebenar; bahagian lain dikekalkan sebagai ansur maju.", "resources": ["Tilam", "Senarai guru"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Mencuba ringkuk separa dan baring ke duduk dengan bimbingan serta bantuan yang dicatat.", "materials": ["Tilam rata"], "teacher": ["Guru membantu posisi lutut melalui arahan dan contoh.", "Benarkan tangan membantu semasa bangun jika perlu; jangan menarik tubuh."], "pupil_steps": ["Baring dengan lutut selesa dan lakukan ringkuk separa kecil.", "Turun perlahan dan rehat sebelum percubaan seterusnya.", "Cuba baring ke duduk dengan cara yang guru benarkan; catat penggunaan tangan.", "Namakan abdomen dan sebut otot boleh bekerja berulang-ulang."], "product": "Dua percubaan individu serta respons otot dan daya tahan.", "criterion": "Lakuan selamat diutamakan; bantuan bukan bukti tanpa sokongan.", "next_step": "Kekalkan ringkuk kecil dan latihan posisi jika duduk penuh belum sesuai.", "example": {"teacher": "Otot apa membantu pergerakan ini?", "pupil": "Otot abdomen di perut."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Mengawal ringkuk separa dan peralihan baring ke duduk.", "materials": ["Tilam", "Jam guru"], "teacher": ["Perhatikan bahu dan leher tanpa meminta ulangan maksimum.", "Pisahkan rekod ringkuk separa daripada rekod baring ke duduk."], "pupil_steps": ["Lakukan ringkuk separa dengan bahu terangkat sedikit.", "Turun perlahan dan berehat.", "Cuba baring ke duduk tanpa sokongan jika mampu; catat jika tangan diperlukan.", "Sebut otot abdomen dan kelebihan bekerja berulang-ulang."], "product": "Dua lakuan yang berbeza serta penerangan sendiri.", "criterion": "Perbezaan penamat jelas; bantuan dan tempoh sebenar dicatat.", "next_step": "Perkemas cara turun tanpa menambah jumlah.", "example": {"teacher": "Apakah beza dua lakuan tadi?", "pupil": "Ringkuk separa angkat bahu sedikit; satu lagi sampai duduk."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas cara turun dan bernafas dalam dua lakuan.", "materials": ["Tilam rata"], "teacher": ["Pilih satu pembaikan seperti turun dengan perlahan.", "Jangan tambah beban atau mewajibkan duduk penuh jika belum bersedia."], "pupil_steps": ["Lakukan ringkuk separa sambil bernafas biasa.", "Turunkan bahu perlahan dan rehat.", "Cuba baring ke duduk dengan terkawal mengikut kesediaan.", "Namakan abdomen dan sebut kelebihan otot yang boleh bekerja berulang-ulang, kemudian nyatakan satu pembaikan sendiri."], "product": "Dua percubaan serta pembaikan kawalan.", "criterion": "Kawalan diperbaik tanpa memaksa leher atau usaha maksimum.", "next_step": "Kekalkan rehat dan catat lakuan yang masih memerlukan bantuan.", "example": {"teacher": "Apakah pembaikan kamu?", "pupil": "Saya turun perlahan dan tidak menahan nafas."}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan latihan otot abdomen dengan gerakan yang terkawal mengikut kemampuan.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bimbing posisi Peneroka.", "Pisahkan bukti dua lakuan Pembina.", "Semak cara turun Pencabar."], "individual_check": "Mencuba ringkuk tubi separa dan pergerakan baring ke duduk; bantuan serta perbezaan lakuan dicatat.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian ringkuk separa individu.", "evidence": "Bahu terangkat sedikit dan turun terkawal dengan lutut selesa.", "criterion": "Ringkuk separa dilakukan tanpa menarik leher; jumlah dan bantuan sebenar dicatat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Lakuan separa: ____", "Ulangan sebenar / bantuan: ____", "Belum diperhatikan: ____"]}, "pbd_complementary": {"3.4.4": {"method": "Pemerhatian baring ke duduk individu.", "evidence": "Penamat duduk serta penggunaan tangan atau bantuan orang.", "criterion": "Tanpa sokongan hanya direkod jika murid benar-benar melakukannya sendiri tanpa tangan menolak alas atau tarikan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Percubaan penuh / ansur maju: ____", "Tanpa sokongan / dengan tangan: ____", "Susulan: ____"]}, "4.4.2": {"method": "Soal jawab ringkas selepas rehat.", "evidence": "Kelebihan otot yang boleh bekerja berulang-ulang.", "criterion": "Murid menyebut boleh melakukan pergerakan berulang tanpa cepat letih dengan kata mudah.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Jawapan: ____", "Bantuan / belum didengar: ____"]}, "4.4.3": {"method": "Soal jawab otot bagi dua lakuan.", "evidence": "Murid mengenal otot abdomen atau perut.", "criterion": "Abdomen dikenal sebagai otot yang membantu ringkuk dan baring ke duduk.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Abdomen dikenal: ____", "Bantuan: ____"]}, "5.1.4": {"method": "Pemerhatian giliran tilam dan rehat.", "evidence": "Murid menunggu di sisi dan tidak memegang kaki atau menarik pasangan.", "criterion": "Peraturan dipatuhi; berhenti apabila sakit ialah tindakan selamat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Giliran: ____", "Tiada tarikan pasangan: ____", "Bantuan / belum dilihat: ____"]}}, "intervention": ["Jika leher atau belakang sakit, hentikan latihan dan ikut tindakan sekolah; jangan memaksa percubaan semula.", "Bantuan dan giliran yang belum lengkap disusuli. Bergayut SP3.4.5 kekal belum dilaksanakan."], "book_pages_text": "56, 57", "sp_focus": "", "sp_display": "3.4.6", "complementary": [{"standard_key": "3.4.4", "sp_code": "3.4.4", "sp_text": "Melakukan pergerakan dari baring ke duduk tanpa sokongan.", "sk_code": "3.4", "sk_text": "Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul.", "domain": "psikomotor", "source_label": ""}, {"standard_key": "4.4.2", "sp_code": "4.4.2", "sp_text": "Menyatakan kelebihan mempunyai otot yang boleh bekerja berulang-ulang dalam satu jangka masa.", "sk_code": "4.4", "sk_text": "Mengaplikasi konsep asas kekuatan dan daya tahan otot.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.4.3", "sp_code": "4.4.3", "sp_text": "Mengenal pasti otot utama pada bahagian badan semasa melakukan senaman daya tahan otot.", "sk_code": "4.4", "sk_text": "Mengaplikasi konsep asas kekuatan dan daya tahan otot.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.4", "sp_code": "5.1.4", "sp_text": "Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "draft_sha256": "1fd0f975b1a73ca5a713e4ad1d0488066d9b5466949490c28f7011dd1f8b2b65"}'::jsonb,'[{"kind": "title", "text": "Minggu 37 Sesi 2 — Ringkuk tubi separa dan baring ke duduk"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W37-S2"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 8: Cergas dan Mantap"}, {"kind": "p", "text": "Tajuk buku teks: Siapa Kuat?"}, {"kind": "p", "text": "Aktiviti guru: Ringkuk tubi separa dan baring ke duduk"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 56, 57."}, {"kind": "p", "text": "Cadangan set singkat sehingga 10 saat dalam rujukan 10–15 saat buku, dengan rehat antara percubaan. Boleh lebih pendek; masa sebenar dan bantuan dicatat. Semua termasuk 30 minit."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.4: Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul."}, {"kind": "p", "text": "SP utama 3.4.6: Melakukan ringkuk tubi separa."}, {"kind": "p", "text": "SK sokongan 3.4: Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul."}, {"kind": "p", "text": "SP sokongan 3.4.4: Melakukan pergerakan dari baring ke duduk tanpa sokongan."}, {"kind": "p", "text": "SK sokongan 4.4: Mengaplikasi konsep asas kekuatan dan daya tahan otot."}, {"kind": "p", "text": "SP sokongan 4.4.2: Menyatakan kelebihan mempunyai otot yang boleh bekerja berulang-ulang dalam satu jangka masa."}, {"kind": "p", "text": "SK sokongan 4.4: Mengaplikasi konsep asas kekuatan dan daya tahan otot."}, {"kind": "p", "text": "SP sokongan 4.4.3: Mengenal pasti otot utama pada bahagian badan semasa melakukan senaman daya tahan otot."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.4: Mengenali dan mematuhi peraturan keselamatan di tempat melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "SP3.4.5 bergayut/meniti belum dilaksanakan kerana tiada palang sesuai."}, {"kind": "p", "text": "SP sumber yang belum dilaksanakan atau belum lengkap: 3.4.5 — Melakukan aktiviti bergayut dan meniti pada palang menggunakan tangan. Tiada palang sesuai; tidak diganti dengan perabot atau bingkai pintu."}, {"kind": "p", "text": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan latihan otot abdomen dengan gerakan yang terkawal mengikut kemampuan."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Mencuba ringkuk tubi separa dan pergerakan baring ke duduk; bantuan serta perbezaan lakuan dicatat."}, {"kind": "p", "text": "2. Menyebut kelebihan otot yang boleh bekerja berulang-ulang dan mengenal otot abdomen."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid tahu menggunakan tilam, menjaga jarak dan berehat apabila perlu."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Tilam atau alas senaman rata"}, {"kind": "p", "text": "Keperluan: Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak."}, {"kind": "p", "text": "Kegunaan: Seorang berlatih sementara pasangan menunggu di sisi tanpa menyokong tubuh."}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: Empat kon di luar tilam dan ruang pijakan."}, {"kind": "p", "text": "Kegunaan: Menandakan ruang latihan serta rehat."}, {"kind": "label", "text": "Jam guru dan air minuman sendiri"}, {"kind": "p", "text": "Keperluan: Satu jam guru; botol sendiri mengikut keperluan."}, {"kind": "p", "text": "Kegunaan: Masa tahan pendek, rehat dan pertukaran giliran."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Guru memeriksa alas rata dan menyediakan satu ruang selamat setiap pasangan."}, {"kind": "p", "text": "2. Tunjukkan perbezaan ringkuk separa dengan baring ke duduk sebelum menilai. Jangan menggunakan nama kedua-duanya untuk lakuan yang sama."}, {"kind": "p", "text": "3. Guru memilih murid yang bersedia untuk percubaan baring ke duduk. Bantuan tangan dibenarkan sebagai ansur maju dan direkod, bukan dianggap tanpa sokongan."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. A menggunakan alas sementara B menunggu di sisi; kemudian bertukar. Tiada pasangan memegang kaki atau menarik tangan."}, {"kind": "p", "text": "2. Setiap murid mencuba kedua-dua lakuan mengikut kesediaan. Guru menghentikan kelas jika perlu memberikan bantuan dekat."}, {"kind": "p", "text": "3. Cadangan dua atau tiga ulangan ringkuk dalam tempoh sehingga 10 saat, kemudian rehat sekurang-kurangnya 20 saat. Jangan berlumba menghabiskan ulangan."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Ringkuk tubi separa: baring terlentang, lutut dibengkokkan selesa dan tapak kaki di alas. Tangan di paha atau di sisi; angkat bahu sedikit sambil menggelongsorkan tangan ke arah lutut, kemudian turun perlahan."}, {"kind": "p", "text": "2. Kepala seiring badan; jangan menarik leher atau menolak dagu kuat. Bernafas seperti biasa sepanjang pergerakan."}, {"kind": "p", "text": "3. Baring ke duduk: daripada baring dengan lutut selesa, cuba naik ke duduk secara terkawal tanpa ditarik rakan. Hanya murid bersedia mencuba tanpa tangan menolak alas; jika tangan diperlukan, catat sebagai bantuan."}, {"kind": "p", "text": "4. Ringkuk separa hanya mengangkat bahu sedikit, manakala baring ke duduk berakhir dalam duduk. Jangan memaksa murid menyiapkan lakuan penuh."}, {"kind": "p", "text": "5. Otot abdomen di bahagian perut membantu pergerakan ini. Daya tahan otot membolehkan otot bekerja berulang-ulang dalam tempoh tertentu, contohnya bangun atau bergerak beberapa kali tanpa cepat letih."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Tilam atau alas senaman rata — Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak."}, {"kind": "p", "text": "2. Kon penanda — Empat kon di luar tilam dan ruang pijakan."}, {"kind": "p", "text": "3. Jam guru dan air minuman sendiri — Satu jam guru; botol sendiri mengikut keperluan."}, {"kind": "p", "text": "4. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Tiada palang sesuai. Aktiviti bergayut dan meniti SP3.4.5 belum dilaksanakan; jangan menggunakan meja, kerusi, pintu atau palang sementara."}, {"kind": "p", "text": "5. Latihan mengikut kemampuan, bukan pertandingan masa atau ulangan. Bernafas seperti biasa; berhenti jika sakit, pening atau sukar bernafas."}, {"kind": "p", "text": "6. Murid tidak memegang kaki, menarik tangan atau menekan tubuh rakan. Bantuan mengubah tahap lakuan dan mesti dicatat."}, {"kind": "p", "text": "7. Guru menunjukkan postur dengan jelas. Jika bentuk tidak dapat dikekalkan, lepaskan posisi dan rehat; jangan memaksa tahan sehingga menggigil atau sakit."}, {"kind": "p", "text": "8. Jangan merapatkan siku ke lutut secara paksa, menarik kepala dengan tangan atau meletakkan beban pada perut. Sakit belakang atau leher memerlukan berhenti dan perhatian guru."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Tilam atau alas senaman rata Kon penanda Jam guru dan air minuman sendiri"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Bezakan dua lakuan — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan ringkuk separa dengan lutut selesa dan bahu terangkat sedikit."}, {"kind": "p", "text": "2. Guru menunjukkan baring ke duduk sebagai lakuan berbeza serta cara berhenti jika belum bersedia."}, {"kind": "p", "text": "3. Guru menamakan abdomen dan menjelaskan daya tahan melalui kata bekerja berulang-ulang."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid melihat perbezaan penamat dua lakuan."}, {"kind": "p", "text": "2. Murid menyebut ringkuk separa atau duduk apabila ditanya."}, {"kind": "p", "text": "Semakan: Murid tidak menyamakan separa dengan lakuan duduk penuh."}, {"kind": "p", "text": "Alatan: Tilam"}, {"kind": "h3", "text": "Langkah 4: Ringkuk separa dengan rehat — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Gunakan satu minit untuk posisi awal. Beri tiga minit kepada A dan tiga minit kepada B untuk ringkuk separa dalam set pendek, diselang rehat."}, {"kind": "p", "text": "2. Guru membimbing dua atau tiga ulangan perlahan jika mampu; jangan mengejar jumlah."}, {"kind": "p", "text": "3. Gunakan dua minit akhir untuk rehat/minum serta percubaan awal baring ke duduk yang dipantau guru."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid baring dengan lutut dibengkokkan dan kaki stabil."}, {"kind": "p", "text": "2. Murid mengangkat bahu sedikit, turun perlahan dan berehat antara set."}, {"kind": "p", "text": "3. Murid mencuba baring ke duduk jika guru membenarkan; bantuan tangan tidak disembunyikan."}, {"kind": "p", "text": "Semakan: Kawalan ringkuk dan percubaan duduk diperhatikan berasingan."}, {"kind": "p", "text": "Alatan: Tilam Jam Air sendiri"}, {"kind": "h3", "text": "Langkah 5: Giliran baring ke duduk — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Beri dua minit setiap giliran A dan B untuk percubaan baring ke duduk dan satu pembetulan ringkuk yang perlu."}, {"kind": "p", "text": "2. Beri satu minit rehat dan dua minit soal jawab tentang abdomen serta kelebihan otot bekerja berulang-ulang."}, {"kind": "p", "text": "3. Catat belum bersedia jika lakuan penuh tidak dilakukan; jangan menarik tangan murid untuk melengkapkannya."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid melakukan percubaan sendiri tanpa pasangan memegang kaki."}, {"kind": "p", "text": "2. Murid menyebut abdomen atau otot perut serta satu kelebihan daya tahan."}, {"kind": "p", "text": "3. Murid menunggu di sisi dan berhenti apabila diarahkan."}, {"kind": "p", "text": "Semakan: Bukti tanpa sokongan hanya diberi pada lakuan sebenar; bahagian lain dikekalkan sebagai ansur maju."}, {"kind": "p", "text": "Alatan: Tilam Senarai guru"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Angkat bahu sedikit sahaja untuk ringkuk separa. Baring ke duduk ialah lakuan lain; jangan paksa jika belum mampu."}, {"kind": "p", "text": "Murid: Murid melakukan lakuan yang dibenarkan dan turun perlahan tanpa rakan memegang kaki."}, {"kind": "p", "text": "Semakan guru: Guru membezakan dua bukti dan merekod bantuan tangan serta tempoh sebenar."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W37-S2"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan latihan otot abdomen dengan gerakan yang terkawal mengikut kemampuan."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bimbing posisi Peneroka."}, {"kind": "p", "text": "2. Pisahkan bukti dua lakuan Pembina."}, {"kind": "p", "text": "3. Semak cara turun Pencabar."}, {"kind": "p", "text": "Semakan individu: Mencuba ringkuk tubi separa dan pergerakan baring ke duduk; bantuan serta perbezaan lakuan dicatat."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Mencuba ringkuk separa dan baring ke duduk dengan bimbingan serta bantuan yang dicatat."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam rata"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru membantu posisi lutut melalui arahan dan contoh."}, {"kind": "p", "text": "2. Benarkan tangan membantu semasa bangun jika perlu; jangan menarik tubuh."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Baring dengan lutut selesa dan lakukan ringkuk separa kecil."}, {"kind": "p", "text": "2. Turun perlahan dan rehat sebelum percubaan seterusnya."}, {"kind": "p", "text": "3. Cuba baring ke duduk dengan cara yang guru benarkan; catat penggunaan tangan."}, {"kind": "p", "text": "4. Namakan abdomen dan sebut otot boleh bekerja berulang-ulang."}, {"kind": "p", "text": "Contoh guru: Otot apa membantu pergerakan ini?"}, {"kind": "p", "text": "Contoh respons murid: Otot abdomen di perut."}, {"kind": "p", "text": "Hasil individu: Dua percubaan individu serta respons otot dan daya tahan."}, {"kind": "p", "text": "Kriteria: Lakuan selamat diutamakan; bantuan bukan bukti tanpa sokongan."}, {"kind": "p", "text": "Susulan: Kekalkan ringkuk kecil dan latihan posisi jika duduk penuh belum sesuai."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Mengawal ringkuk separa dan peralihan baring ke duduk."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam"}, {"kind": "p", "text": "2. Jam guru"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Perhatikan bahu dan leher tanpa meminta ulangan maksimum."}, {"kind": "p", "text": "2. Pisahkan rekod ringkuk separa daripada rekod baring ke duduk."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Lakukan ringkuk separa dengan bahu terangkat sedikit."}, {"kind": "p", "text": "2. Turun perlahan dan berehat."}, {"kind": "p", "text": "3. Cuba baring ke duduk tanpa sokongan jika mampu; catat jika tangan diperlukan."}, {"kind": "p", "text": "4. Sebut otot abdomen dan kelebihan bekerja berulang-ulang."}, {"kind": "p", "text": "Contoh guru: Apakah beza dua lakuan tadi?"}, {"kind": "p", "text": "Contoh respons murid: Ringkuk separa angkat bahu sedikit; satu lagi sampai duduk."}, {"kind": "p", "text": "Hasil individu: Dua lakuan yang berbeza serta penerangan sendiri."}, {"kind": "p", "text": "Kriteria: Perbezaan penamat jelas; bantuan dan tempoh sebenar dicatat."}, {"kind": "p", "text": "Susulan: Perkemas cara turun tanpa menambah jumlah."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas cara turun dan bernafas dalam dua lakuan."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam rata"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Pilih satu pembaikan seperti turun dengan perlahan."}, {"kind": "p", "text": "2. Jangan tambah beban atau mewajibkan duduk penuh jika belum bersedia."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Lakukan ringkuk separa sambil bernafas biasa."}, {"kind": "p", "text": "2. Turunkan bahu perlahan dan rehat."}, {"kind": "p", "text": "3. Cuba baring ke duduk dengan terkawal mengikut kesediaan."}, {"kind": "p", "text": "4. Namakan abdomen dan sebut kelebihan otot yang boleh bekerja berulang-ulang, kemudian nyatakan satu pembaikan sendiri."}, {"kind": "p", "text": "Contoh guru: Apakah pembaikan kamu?"}, {"kind": "p", "text": "Contoh respons murid: Saya turun perlahan dan tidak menahan nafas."}, {"kind": "p", "text": "Hasil individu: Dua percubaan serta pembaikan kawalan."}, {"kind": "p", "text": "Kriteria: Kawalan diperbaik tanpa memaksa leher atau usaha maksimum."}, {"kind": "p", "text": "Susulan: Kekalkan rehat dan catat lakuan yang masih memerlukan bantuan."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.4.6"}, {"kind": "p", "text": "Kaedah: Pemerhatian ringkuk separa individu."}, {"kind": "p", "text": "Bukti: Bahu terangkat sedikit dan turun terkawal dengan lutut selesa."}, {"kind": "p", "text": "Kriteria: Ringkuk separa dilakukan tanpa menarik leher; jumlah dan bantuan sebenar dicatat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Lakuan separa: ____"}, {"kind": "p", "text": "2. Ulangan sebenar / bantuan: ____"}, {"kind": "p", "text": "3. Belum diperhatikan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 3.4.4"}, {"kind": "p", "text": "Kaedah: Pemerhatian baring ke duduk individu."}, {"kind": "p", "text": "Bukti: Penamat duduk serta penggunaan tangan atau bantuan orang."}, {"kind": "p", "text": "Kriteria: Tanpa sokongan hanya direkod jika murid benar-benar melakukannya sendiri tanpa tangan menolak alas atau tarikan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Percubaan penuh / ansur maju: ____"}, {"kind": "p", "text": "2. Tanpa sokongan / dengan tangan: ____"}, {"kind": "p", "text": "3. Susulan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.4.2"}, {"kind": "p", "text": "Kaedah: Soal jawab ringkas selepas rehat."}, {"kind": "p", "text": "Bukti: Kelebihan otot yang boleh bekerja berulang-ulang."}, {"kind": "p", "text": "Kriteria: Murid menyebut boleh melakukan pergerakan berulang tanpa cepat letih dengan kata mudah."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Jawapan: ____"}, {"kind": "p", "text": "2. Bantuan / belum didengar: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.4.3"}, {"kind": "p", "text": "Kaedah: Soal jawab otot bagi dua lakuan."}, {"kind": "p", "text": "Bukti: Murid mengenal otot abdomen atau perut."}, {"kind": "p", "text": "Kriteria: Abdomen dikenal sebagai otot yang membantu ringkuk dan baring ke duduk."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Abdomen dikenal: ____"}, {"kind": "p", "text": "2. Bantuan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.4"}, {"kind": "p", "text": "Kaedah: Pemerhatian giliran tilam dan rehat."}, {"kind": "p", "text": "Bukti: Murid menunggu di sisi dan tidak memegang kaki atau menarik pasangan."}, {"kind": "p", "text": "Kriteria: Peraturan dipatuhi; berhenti apabila sakit ialah tindakan selamat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Giliran: ____"}, {"kind": "p", "text": "2. Tiada tarikan pasangan: ____"}, {"kind": "p", "text": "3. Bantuan / belum dilihat: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Jika leher atau belakang sakit, hentikan latihan dan ikut tindakan sekolah; jangan memaksa percubaan semula."}, {"kind": "p", "text": "2. Bantuan dan giliran yang belum lengkap disusuli. Bergayut SP3.4.5 kekal belum dilaksanakan."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Tiada palang sesuai. SP3.4.5 bergayut/meniti belum dilaksanakan dan tiada alatan rumah dijadikan pengganti. S1 melatih posisi sedia tekan tubi, separa cangkung serta duduk ke berdiri; S2 ringkuk tubi separa serta baring ke duduk. Tempoh pendek dan bantuan ikut kemampuan; bantuan tidak dianggap lakuan tanpa sokongan.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W38-S1','pj',1,2026,38,1,30,'3.4.7',array[58,59]::int[],'996161d5514c686b4170a6fc31ce14736b6d62c8d0ef1a0a939dad0521851e77','1912ab4f589d37ce9175d0868f62ffb4f0fd0596d7bcb2f43e091f6f873a509a','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W38-S1", "subject": "Pendidikan Jasmani", "year": 1, "week": 38, "session": 1, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Stabil dan Seimbang", "source_title": "Stabil dan Seimbang", "unit": "Unit 8: Cergas dan Mantap", "source_row_id": "PJ1-RPT2026-T14-R2", "source_row_literal": ["38\n\nKump A: 15.11.2026-19.11.2026\n\nKump B: 26.10.2026- 30.10.2026", "8: CERGAS DAN MANTAP\n\nSTABIL DAN SEIMBANG", "3.4 Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul \n\n4.4 Mengaplikasi konsep asas kekuatan dan daya tahan otot. \n\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "3.4.7  Melakukan aktiviti untuk membina \notot teras badan (core muscle).\n\n4.4.3  Mengenal pasti otot utama pada \n          bahagian badan semasa \n          melakukan aktiviti kekuatan dan \n          daya tahan otot.\n\n5.1.3 Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "Pemerhatian /\nPentaksiran\n\n\n\n\nBT m/s 58-59"], "rpt_original_page_literal": "58-59", "source_pages": [58, 59], "source_pdf_pages": [66, 67], "rpt_book_pages": "58, 59", "main_standard_key": "3.4.7", "sk_code": "3.4", "sk_text": "Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul.", "sp_code": "3.4.7", "sp_text": "Melakukan senaman untuk membina otot teras badan (core mucsle).", "complementary_standards": [{"standard_key": "4.4.3", "sp_code": "4.4.3", "sp_text": "Mengenal pasti otot utama pada bahagian badan semasa melakukan senaman daya tahan otot.", "sk_code": "4.4", "sk_text": "Mengaplikasi konsep asas kekuatan dan daya tahan otot.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "source_task": "Menguatkan otot teras dengan gerakan kecil", "authoring_focus": "Menguatkan otot teras dengan gerakan kecil", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": true, "source_subset_note": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap.", "adaptation_note": "Guru membenarkan pecahan M38: S1 otot teras BT58–59, S2 ukuran sebenar secara sulit BT60–61. Baris Badan Idaman berkongsi sel minggu38 melalui WordvMerge. Contoh bentuk badan rekaan digunakan tanpa melabel atau mendiagnosis murid. Tiada BMI, sasaran berat atau perbandingan data rakan. Ukuran yang belum diperoleh dicatat untuk susulan.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": [], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Tiada lentikan tinggi, dongak kuat, beban atas badan, tarikan pasangan atau tahan nafas.", "Jika sakit belakang, leher, pening atau sukar bernafas, lepaskan posisi dan beritahu guru.", "Murid tidak perlu membuat semua enam contoh buku. Gerakan lain yang belum diajar tidak dianggap dikuasai.", "Istilah abdomen digunakan untuk mengenal otot, bukan melabel saiz atau bentuk perut murid."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Gerakan abdomen dan angkat pinggul dengan terkawal", "objective": "Murid dapat melakukan senaman otot teras dengan pergerakan yang kecil dan selamat.", "success_criteria": ["Mencuba mengempis abdomen dan baring mengangkat pinggul dengan nafas biasa serta kawalan.", "Mengenal otot abdomen dan pinggul atau belakang bawah yang membantu gerakan."], "prior_knowledge": "Murid pernah menggunakan tilam dan mencuba latihan otot mengikut kemampuan.", "equipment": [{"item": "Tilam atau alas senaman rata", "quantity": "Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak.", "use": "Seorang berlatih sementara pasangan menunggu di sisi tanpa menyokong tubuh."}, {"item": "Kon penanda", "quantity": "Empat kon di luar tilam dan ruang pijakan.", "use": "Menandakan ruang latihan serta rehat."}, {"item": "Jam guru dan air minuman sendiri", "quantity": "Satu jam guru; botol sendiri mengikut keperluan.", "use": "Masa tahan pendek, rehat dan pertukaran giliran."}], "preparation": ["Guru memilih dua gerakan daripada BT58–59: mengempis abdomen dan baring mengangkat pinggul. Tidak perlu melakukan semua enam gambar.", "Sediakan alas rata setiap pasangan dan ruang menunggu di sisi. Tiada beban atau bantuan menarik anggota pasangan.", "Guru menyemak kesediaan serta memilih angkatan pinggul kecil; hentikan jika sakit belakang atau leher."], "organisation": ["A menggunakan alas sementara B menunggu di sisi, kemudian bertukar. Setiap murid mendapat kedua-dua gerakan.", "Semua aktiviti berhenti apabila guru perlu bantuan dekat. Murid yang menunggu tidak melakukan gerakan sukar tanpa pengawasan.", "Cadangan tiga ulangan perlahan setiap gerakan dengan rehat. Tahanan pendek sekitar tiga saat sahaja jika selesa; bukan arahan menahan nafas."], "movement_cues": ["Mengempis abdomen: baring terlentang, lutut dibengkokkan dan kaki selesa di alas. Ketatkan sedikit otot perut seolah-olah merapatkan pusat ke arah belakang, kemudian lepaskan sambil bernafas biasa.", "Jangan menyedut atau menahan nafas kuat. Gerakan kecil dan rasa otot bekerja sudah memadai.", "Angkat pinggul: dari baring lutut bengkok, kaki stabil, tangan di sisi. Angkat pinggul sedikit dengan bahu dan kepala kekal di alas, kemudian turun perlahan.", "Jangan melentik tinggi, menekan leher atau menolak badan rakan. Jika belum mampu, latihan menegangkan abdomen sahaja direkod sebagai ansur maju bagi gerakan pinggul.", "Otot abdomen membantu mengawal bahagian perut. Otot pinggul dan belakang bawah membantu angkatan pinggul; senaman teras bukan sasaran mengecilkan perut atau menurunkan berat."], "timing_note": "Dua gerakan teras dipilih sebagai subset contoh BT58–59. Masa latihan, rehat, giliran dan penyejukan dalam 30 minit; tidak mendakwa semua contoh buku dilatih.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Angkat pinggul sedikit sahaja, kemudian turun perlahan. Terus bernafas.", "pupils_do": "Murid mengangkat mengikut keselesaan dengan kepala dan bahu di alas.", "teacher_checks": "Guru menyemak tiada lentikan tinggi atau tekanan leher dan mencatat bantuan."}, "bbm": ["Tilam atau alas senaman rata — Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak.", "Kon penanda — Empat kon di luar tilam dan ruang pijakan.", "Jam guru dan air minuman sendiri — Satu jam guru; botol sendiri mengikut keperluan.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Tilam atau alas senaman rata", "Kon penanda", "Jam guru dan air minuman sendiri"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Kenal dua gerakan teras", "minutes": 4, "teacher": ["Guru menunjukkan mengempis abdomen dengan nafas biasa dalam posisi baring lutut bengkok.", "Guru menunjukkan angkat pinggul sedikit dan turun perlahan; namakan abdomen, pinggul dan belakang bawah."], "pupils": ["Murid melihat kedudukan kaki, bahu dan kepala.", "Murid menyebut satu bahagian otot tanpa menyentuh tubuh rakan."], "check": "Dua gerakan jelas; bukan semua gambar teras diwajibkan.", "resources": ["Tilam"]}, {"name": "Cuba dan lepaskan perlahan", "minutes": 9, "teacher": ["Gunakan satu minit untuk menyemak posisi awal. Beri tiga minit kepada A dan tiga minit kepada B bagi kedua-dua gerakan: tiga ulangan kecil jika mampu dengan rehat antara gerakan.", "Guru mengingatkan nafas biasa dan angkatan rendah. Jika bentuk hilang atau sakit, hentikan.", "Gunakan dua minit akhir untuk rehat/minum dan soalan otot utama."], "pupils": ["Murid mengetatkan sedikit abdomen dan melepaskannya.", "Murid mencuba angkat pinggul rendah, kemudian turun perlahan.", "Murid berehat dan memberi giliran pasangan tanpa membantu tubuhnya."], "check": "Kedua-dua gerakan dilakukan sendiri, atau tahap ansur maju dicatat.", "resources": ["Tilam", "Jam", "Air sendiri"]}, {"name": "Semak satu pembaikan", "minutes": 7, "teacher": ["Beri dua minit bagi A dan dua minit bagi B untuk mengulang satu perkara yang perlu dibaiki, sambil memastikan bukti kedua-dua gerakan sudah diperhatikan.", "Beri satu minit rehat dan dua minit soalan abdomen serta pinggul/belakang bawah.", "Catat gerakan yang belum dilakukan; jangan memaksa angkatan untuk mencukupkan rekod."], "pupils": ["Murid melakukan pembaikan seperti turun perlahan atau terus bernafas.", "Murid menyebut abdomen dan pinggul atau belakang bawah dengan bantuan kata.", "Murid mematuhi arahan berhenti dan kembali ke tempat menunggu."], "check": "Guru menilai kawalan dan mengenal otot, bukan jumlah maksimum atau bentuk tubuh.", "resources": ["Tilam", "Senarai guru"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Mencuba dua gerakan teras dengan contoh kecil guru.", "materials": ["Tilam rata"], "teacher": ["Guru memberi arahan abdomen dan pinggul satu demi satu.", "Benarkan angkatan sangat kecil atau kembali kepada posisi awal; catat bahagian belum dibuat."], "pupil_steps": ["Baring dengan lutut bengkok dan kaki stabil.", "Cuba mengempis abdomen sedikit dengan nafas biasa.", "Cuba angkat pinggul rendah jika bersedia dan turun perlahan.", "Sebut abdomen dan pinggul atau belakang bawah serta minta bantuan jika perlu."], "product": "Dua percubaan atau ansur maju yang direkod, serta respons otot.", "criterion": "Lakuan kecil selamat; abdomen sahaja tidak dianggap sudah melakukan angkatan pinggul.", "next_step": "Ulang posisi awal tanpa mengangkat jika belum bersedia.", "example": {"teacher": "Perlu tahan nafas?", "pupil": "Tidak. Bernafas seperti biasa."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Melakukan abdomen dan angkat pinggul mengikut giliran.", "materials": ["Tilam", "Jam guru"], "teacher": ["Semak kaki serta bahu stabil.", "Beri satu petunjuk untuk menurunkan pinggul perlahan."], "pupil_steps": ["Sediakan posisi baring lutut bengkok.", "Lakukan gerakan mengempis abdomen dan lepaskan.", "Angkat pinggul sedikit dan turunkan dengan kawalan.", "Namakan abdomen serta pinggul/belakang bawah yang membantu gerakan."], "product": "Dua gerakan individu dan jawapan otot utama.", "criterion": "Nafas biasa dan kawalan dikekalkan; bantuan serta rehat dicatat.", "next_step": "Perkemas satu gerakan tanpa menambah tinggi atau masa.", "example": {"teacher": "Otot apa membantu gerakan perut?", "pupil": "Otot abdomen."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas kawalan turun dalam dua gerakan teras.", "materials": ["Tilam rata"], "teacher": ["Kekalkan angkatan rendah dan jumlah yang sama.", "Jangan minta tahan lebih lama atau menambah beban."], "pupil_steps": ["Lakukan abdomen dengan bahu santai.", "Lepaskan ketegangan kecil sambil bernafas biasa.", "Lakukan angkat pinggul rendah dan turun perlahan.", "Sebut otot abdomen serta pinggul/belakang bawah dan satu pembaikan kawalan."], "product": "Dua gerakan dengan satu pembaikan selamat.", "criterion": "Kawalan bertambah tanpa tekanan leher atau paksaan.", "next_step": "Kekalkan petunjuk kawalan dalam latihan susulan.", "example": {"teacher": "Apakah yang kamu baiki?", "pupil": "Saya turun perlahan dan tidak melentik tinggi."}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan senaman otot teras dengan pergerakan yang kecil dan selamat.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bantu posisi Peneroka.", "Semak dua gerakan Pembina.", "Perhatikan kawalan turun Pencabar."], "individual_check": "Mencuba mengempis abdomen dan baring mengangkat pinggul dengan nafas biasa serta kawalan.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian individu terhadap dua contoh teras yang dipilih.", "evidence": "Mengempis abdomen dan baring mengangkat pinggul murid sendiri.", "criterion": "Kedua-dua contoh dilakukan dengan nafas biasa dan julat selesa. Bahagian yang belum dibuat dicatat; bukan dakwaan semua contoh buku dikuasai.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Abdomen: ____", "Angkat pinggul: ____", "Bantuan / ansur maju / belum dilihat: ____"]}, "pbd_complementary": {"4.4.3": {"method": "Soal jawab ringkas selepas rehat.", "evidence": "Murid menamakan abdomen dan pinggul atau belakang bawah.", "criterion": "Otot utama dihubungkan dengan contoh gerakan yang dilakukan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Abdomen: ____", "Pinggul atau belakang bawah: ____", "Bantuan: ____"]}, "5.1.3": {"method": "Pemerhatian giliran dan respons berhenti.", "evidence": "Murid menggunakan alas pada giliran dan melepaskan posisi apabila diarahkan.", "criterion": "Arahan dipatuhi tanpa membantu atau menarik tubuh rakan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Giliran: ____", "Berhenti/rehat: ____", "Belum dilihat: ____"]}}, "intervention": ["Jika gerakan pinggul belum sesuai, rekod ansur maju abdomen dan rancang bimbingan lanjut; jangan memaksa.", "Sebarang kesakitan ditangani mengikut tatacara sekolah; tiada tugasan latihan sukar sendiri di rumah."], "book_pages_text": "58, 59", "sp_focus": "", "sp_display": "3.4.7", "complementary": [{"standard_key": "4.4.3", "sp_code": "4.4.3", "sp_text": "Mengenal pasti otot utama pada bahagian badan semasa melakukan senaman daya tahan otot.", "sk_code": "4.4", "sk_text": "Mengaplikasi konsep asas kekuatan dan daya tahan otot.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.3", "sp_code": "5.1.3", "sp_text": "Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "draft_sha256": "322786482ddccb0225ce5de0c93f629cb907d4e07f02a9d1664dbf97dbade88f"}'::jsonb,'[{"kind": "title", "text": "Minggu 38 Sesi 1 — Gerakan abdomen dan angkat pinggul dengan terkawal"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W38-S1"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 8: Cergas dan Mantap"}, {"kind": "p", "text": "Tajuk buku teks: Stabil dan Seimbang"}, {"kind": "p", "text": "Aktiviti guru: Gerakan abdomen dan angkat pinggul dengan terkawal"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 58, 59."}, {"kind": "p", "text": "Dua gerakan teras dipilih sebagai subset contoh BT58–59. Masa latihan, rehat, giliran dan penyejukan dalam 30 minit; tidak mendakwa semua contoh buku dilatih."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.4: Melakukan senaman meningkatkan daya tahan dan kekuatan otot dengan lakuan yang betul."}, {"kind": "p", "text": "SP utama 3.4.7: Melakukan senaman untuk membina otot teras badan (core mucsle)."}, {"kind": "p", "text": "SK sokongan 4.4: Mengaplikasi konsep asas kekuatan dan daya tahan otot."}, {"kind": "p", "text": "SP sokongan 4.4.3: Mengenal pasti otot utama pada bahagian badan semasa melakukan senaman daya tahan otot."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.3: Mematuhi arahan guru semasa melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan senaman otot teras dengan pergerakan yang kecil dan selamat."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Mencuba mengempis abdomen dan baring mengangkat pinggul dengan nafas biasa serta kawalan."}, {"kind": "p", "text": "2. Mengenal otot abdomen dan pinggul atau belakang bawah yang membantu gerakan."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah menggunakan tilam dan mencuba latihan otot mengikut kemampuan."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Tilam atau alas senaman rata"}, {"kind": "p", "text": "Keperluan: Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak."}, {"kind": "p", "text": "Kegunaan: Seorang berlatih sementara pasangan menunggu di sisi tanpa menyokong tubuh."}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: Empat kon di luar tilam dan ruang pijakan."}, {"kind": "p", "text": "Kegunaan: Menandakan ruang latihan serta rehat."}, {"kind": "label", "text": "Jam guru dan air minuman sendiri"}, {"kind": "p", "text": "Keperluan: Satu jam guru; botol sendiri mengikut keperluan."}, {"kind": "p", "text": "Kegunaan: Masa tahan pendek, rehat dan pertukaran giliran."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Guru memilih dua gerakan daripada BT58–59: mengempis abdomen dan baring mengangkat pinggul. Tidak perlu melakukan semua enam gambar."}, {"kind": "p", "text": "2. Sediakan alas rata setiap pasangan dan ruang menunggu di sisi. Tiada beban atau bantuan menarik anggota pasangan."}, {"kind": "p", "text": "3. Guru menyemak kesediaan serta memilih angkatan pinggul kecil; hentikan jika sakit belakang atau leher."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. A menggunakan alas sementara B menunggu di sisi, kemudian bertukar. Setiap murid mendapat kedua-dua gerakan."}, {"kind": "p", "text": "2. Semua aktiviti berhenti apabila guru perlu bantuan dekat. Murid yang menunggu tidak melakukan gerakan sukar tanpa pengawasan."}, {"kind": "p", "text": "3. Cadangan tiga ulangan perlahan setiap gerakan dengan rehat. Tahanan pendek sekitar tiga saat sahaja jika selesa; bukan arahan menahan nafas."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Mengempis abdomen: baring terlentang, lutut dibengkokkan dan kaki selesa di alas. Ketatkan sedikit otot perut seolah-olah merapatkan pusat ke arah belakang, kemudian lepaskan sambil bernafas biasa."}, {"kind": "p", "text": "2. Jangan menyedut atau menahan nafas kuat. Gerakan kecil dan rasa otot bekerja sudah memadai."}, {"kind": "p", "text": "3. Angkat pinggul: dari baring lutut bengkok, kaki stabil, tangan di sisi. Angkat pinggul sedikit dengan bahu dan kepala kekal di alas, kemudian turun perlahan."}, {"kind": "p", "text": "4. Jangan melentik tinggi, menekan leher atau menolak badan rakan. Jika belum mampu, latihan menegangkan abdomen sahaja direkod sebagai ansur maju bagi gerakan pinggul."}, {"kind": "p", "text": "5. Otot abdomen membantu mengawal bahagian perut. Otot pinggul dan belakang bawah membantu angkatan pinggul; senaman teras bukan sasaran mengecilkan perut atau menurunkan berat."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Tilam atau alas senaman rata — Satu tempat latihan setiap pasangan; tilam bersih dan tidak bergerak."}, {"kind": "p", "text": "2. Kon penanda — Empat kon di luar tilam dan ruang pijakan."}, {"kind": "p", "text": "3. Jam guru dan air minuman sendiri — Satu jam guru; botol sendiri mengikut keperluan."}, {"kind": "p", "text": "4. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Tiada lentikan tinggi, dongak kuat, beban atas badan, tarikan pasangan atau tahan nafas."}, {"kind": "p", "text": "5. Jika sakit belakang, leher, pening atau sukar bernafas, lepaskan posisi dan beritahu guru."}, {"kind": "p", "text": "6. Murid tidak perlu membuat semua enam contoh buku. Gerakan lain yang belum diajar tidak dianggap dikuasai."}, {"kind": "p", "text": "7. Istilah abdomen digunakan untuk mengenal otot, bukan melabel saiz atau bentuk perut murid."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Tilam atau alas senaman rata Kon penanda Jam guru dan air minuman sendiri"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Kenal dua gerakan teras — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan mengempis abdomen dengan nafas biasa dalam posisi baring lutut bengkok."}, {"kind": "p", "text": "2. Guru menunjukkan angkat pinggul sedikit dan turun perlahan; namakan abdomen, pinggul dan belakang bawah."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid melihat kedudukan kaki, bahu dan kepala."}, {"kind": "p", "text": "2. Murid menyebut satu bahagian otot tanpa menyentuh tubuh rakan."}, {"kind": "p", "text": "Semakan: Dua gerakan jelas; bukan semua gambar teras diwajibkan."}, {"kind": "p", "text": "Alatan: Tilam"}, {"kind": "h3", "text": "Langkah 4: Cuba dan lepaskan perlahan — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Gunakan satu minit untuk menyemak posisi awal. Beri tiga minit kepada A dan tiga minit kepada B bagi kedua-dua gerakan: tiga ulangan kecil jika mampu dengan rehat antara gerakan."}, {"kind": "p", "text": "2. Guru mengingatkan nafas biasa dan angkatan rendah. Jika bentuk hilang atau sakit, hentikan."}, {"kind": "p", "text": "3. Gunakan dua minit akhir untuk rehat/minum dan soalan otot utama."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid mengetatkan sedikit abdomen dan melepaskannya."}, {"kind": "p", "text": "2. Murid mencuba angkat pinggul rendah, kemudian turun perlahan."}, {"kind": "p", "text": "3. Murid berehat dan memberi giliran pasangan tanpa membantu tubuhnya."}, {"kind": "p", "text": "Semakan: Kedua-dua gerakan dilakukan sendiri, atau tahap ansur maju dicatat."}, {"kind": "p", "text": "Alatan: Tilam Jam Air sendiri"}, {"kind": "h3", "text": "Langkah 5: Semak satu pembaikan — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Beri dua minit bagi A dan dua minit bagi B untuk mengulang satu perkara yang perlu dibaiki, sambil memastikan bukti kedua-dua gerakan sudah diperhatikan."}, {"kind": "p", "text": "2. Beri satu minit rehat dan dua minit soalan abdomen serta pinggul/belakang bawah."}, {"kind": "p", "text": "3. Catat gerakan yang belum dilakukan; jangan memaksa angkatan untuk mencukupkan rekod."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid melakukan pembaikan seperti turun perlahan atau terus bernafas."}, {"kind": "p", "text": "2. Murid menyebut abdomen dan pinggul atau belakang bawah dengan bantuan kata."}, {"kind": "p", "text": "3. Murid mematuhi arahan berhenti dan kembali ke tempat menunggu."}, {"kind": "p", "text": "Semakan: Guru menilai kawalan dan mengenal otot, bukan jumlah maksimum atau bentuk tubuh."}, {"kind": "p", "text": "Alatan: Tilam Senarai guru"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Angkat pinggul sedikit sahaja, kemudian turun perlahan. Terus bernafas."}, {"kind": "p", "text": "Murid: Murid mengangkat mengikut keselesaan dengan kepala dan bahu di alas."}, {"kind": "p", "text": "Semakan guru: Guru menyemak tiada lentikan tinggi atau tekanan leher dan mencatat bantuan."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W38-S1"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan senaman otot teras dengan pergerakan yang kecil dan selamat."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bantu posisi Peneroka."}, {"kind": "p", "text": "2. Semak dua gerakan Pembina."}, {"kind": "p", "text": "3. Perhatikan kawalan turun Pencabar."}, {"kind": "p", "text": "Semakan individu: Mencuba mengempis abdomen dan baring mengangkat pinggul dengan nafas biasa serta kawalan."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Mencuba dua gerakan teras dengan contoh kecil guru."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam rata"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memberi arahan abdomen dan pinggul satu demi satu."}, {"kind": "p", "text": "2. Benarkan angkatan sangat kecil atau kembali kepada posisi awal; catat bahagian belum dibuat."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Baring dengan lutut bengkok dan kaki stabil."}, {"kind": "p", "text": "2. Cuba mengempis abdomen sedikit dengan nafas biasa."}, {"kind": "p", "text": "3. Cuba angkat pinggul rendah jika bersedia dan turun perlahan."}, {"kind": "p", "text": "4. Sebut abdomen dan pinggul atau belakang bawah serta minta bantuan jika perlu."}, {"kind": "p", "text": "Contoh guru: Perlu tahan nafas?"}, {"kind": "p", "text": "Contoh respons murid: Tidak. Bernafas seperti biasa."}, {"kind": "p", "text": "Hasil individu: Dua percubaan atau ansur maju yang direkod, serta respons otot."}, {"kind": "p", "text": "Kriteria: Lakuan kecil selamat; abdomen sahaja tidak dianggap sudah melakukan angkatan pinggul."}, {"kind": "p", "text": "Susulan: Ulang posisi awal tanpa mengangkat jika belum bersedia."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Melakukan abdomen dan angkat pinggul mengikut giliran."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam"}, {"kind": "p", "text": "2. Jam guru"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Semak kaki serta bahu stabil."}, {"kind": "p", "text": "2. Beri satu petunjuk untuk menurunkan pinggul perlahan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sediakan posisi baring lutut bengkok."}, {"kind": "p", "text": "2. Lakukan gerakan mengempis abdomen dan lepaskan."}, {"kind": "p", "text": "3. Angkat pinggul sedikit dan turunkan dengan kawalan."}, {"kind": "p", "text": "4. Namakan abdomen serta pinggul/belakang bawah yang membantu gerakan."}, {"kind": "p", "text": "Contoh guru: Otot apa membantu gerakan perut?"}, {"kind": "p", "text": "Contoh respons murid: Otot abdomen."}, {"kind": "p", "text": "Hasil individu: Dua gerakan individu dan jawapan otot utama."}, {"kind": "p", "text": "Kriteria: Nafas biasa dan kawalan dikekalkan; bantuan serta rehat dicatat."}, {"kind": "p", "text": "Susulan: Perkemas satu gerakan tanpa menambah tinggi atau masa."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas kawalan turun dalam dua gerakan teras."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Tilam rata"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Kekalkan angkatan rendah dan jumlah yang sama."}, {"kind": "p", "text": "2. Jangan minta tahan lebih lama atau menambah beban."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Lakukan abdomen dengan bahu santai."}, {"kind": "p", "text": "2. Lepaskan ketegangan kecil sambil bernafas biasa."}, {"kind": "p", "text": "3. Lakukan angkat pinggul rendah dan turun perlahan."}, {"kind": "p", "text": "4. Sebut otot abdomen serta pinggul/belakang bawah dan satu pembaikan kawalan."}, {"kind": "p", "text": "Contoh guru: Apakah yang kamu baiki?"}, {"kind": "p", "text": "Contoh respons murid: Saya turun perlahan dan tidak melentik tinggi."}, {"kind": "p", "text": "Hasil individu: Dua gerakan dengan satu pembaikan selamat."}, {"kind": "p", "text": "Kriteria: Kawalan bertambah tanpa tekanan leher atau paksaan."}, {"kind": "p", "text": "Susulan: Kekalkan petunjuk kawalan dalam latihan susulan."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.4.7"}, {"kind": "p", "text": "Kaedah: Pemerhatian individu terhadap dua contoh teras yang dipilih."}, {"kind": "p", "text": "Bukti: Mengempis abdomen dan baring mengangkat pinggul murid sendiri."}, {"kind": "p", "text": "Kriteria: Kedua-dua contoh dilakukan dengan nafas biasa dan julat selesa. Bahagian yang belum dibuat dicatat; bukan dakwaan semua contoh buku dikuasai."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Abdomen: ____"}, {"kind": "p", "text": "2. Angkat pinggul: ____"}, {"kind": "p", "text": "3. Bantuan / ansur maju / belum dilihat: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.4.3"}, {"kind": "p", "text": "Kaedah: Soal jawab ringkas selepas rehat."}, {"kind": "p", "text": "Bukti: Murid menamakan abdomen dan pinggul atau belakang bawah."}, {"kind": "p", "text": "Kriteria: Otot utama dihubungkan dengan contoh gerakan yang dilakukan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Abdomen: ____"}, {"kind": "p", "text": "2. Pinggul atau belakang bawah: ____"}, {"kind": "p", "text": "3. Bantuan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.3"}, {"kind": "p", "text": "Kaedah: Pemerhatian giliran dan respons berhenti."}, {"kind": "p", "text": "Bukti: Murid menggunakan alas pada giliran dan melepaskan posisi apabila diarahkan."}, {"kind": "p", "text": "Kriteria: Arahan dipatuhi tanpa membantu atau menarik tubuh rakan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Giliran: ____"}, {"kind": "p", "text": "2. Berhenti/rehat: ____"}, {"kind": "p", "text": "3. Belum dilihat: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Jika gerakan pinggul belum sesuai, rekod ansur maju abdomen dan rancang bimbingan lanjut; jangan memaksa."}, {"kind": "p", "text": "2. Sebarang kesakitan ditangani mengikut tatacara sekolah; tiada tugasan latihan sukar sendiri di rumah."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Guru membenarkan pecahan M38: S1 otot teras BT58–59, S2 ukuran sebenar secara sulit BT60–61. Baris Badan Idaman berkongsi sel minggu38 melalui WordvMerge. Contoh bentuk badan rekaan digunakan tanpa melabel atau mendiagnosis murid. Tiada BMI, sasaran berat atau perbandingan data rakan. Ukuran yang belum diperoleh dicatat untuk susulan.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W38-S2','pj',1,2026,38,2,30,'3.5.1',array[60,61]::int[],'3c3f4ab6f3c6d7e2daed3090136ae7bf1c694af70ad89f9fcb491681645cb3e3','5f6e01221fe3ee2dedf8f8d704ff22540321202f973951e1911d65321497ac4f','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W38-S2", "subject": "Pendidikan Jasmani", "year": 1, "week": 38, "session": 2, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Badan Idaman", "source_title": "Badan Idaman", "unit": "Unit 8: Cergas dan Mantap", "source_row_id": "PJ1-RPT2026-T14-R3", "source_row_literal": ["", "8: CERGAS DAN MANTAP\n\nBADAN IDAMAN", "3.5 Melakukan aktiviti yang melibatkan komposisi badan.\n4.5 Membuat perkaitan antara komposisi badan dengan kecergasan fizikal.\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "3.5.1 Mengukur ketinggian dan menimbang berat badan.\n\n4.5.1 Mengenal pasti komponen dalam badan iaitu tulang, otot, organ, dan lemak. \n\n4.5.2 Mengenali bentuk badan kurus, sederhana, dan berlebihan berat badan.\n\n5.1.1 Membuat persediaan diri sebelum, semasa, dan selepas melakukan aktiviti Pendidikan Jasmani.", "Pemerhatian /\nPentaksiran\n\nPermainan kecil:\nSiapa tinggi, siapa berat\n\n\nBT m/s 60-61"], "rpt_original_page_literal": "60-61", "source_pages": [60, 61], "source_pdf_pages": [68, 69], "rpt_book_pages": "60, 61", "main_standard_key": "3.5.1", "sk_code": "3.5", "sk_text": "Melakukan aktiviti yang melibatkan komposisi badan.", "sp_code": "3.5.1", "sp_text": "Mengukur ketinggian dan menimbang berat badan.", "complementary_standards": [{"standard_key": "4.5.1", "sp_code": "4.5.1", "sp_text": "Mengenal pasti komponen dalam badan iaitu tulang, otot, organ dan lemak.", "sk_code": "4.5", "sk_text": "Membuat perkaitan antara komposisi badan dengan kecergasan fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.5.2", "sp_code": "4.5.2", "sp_text": "Mengenali bentuk badan kurus, sederhana dan berlebihan berat badan.", "sk_code": "4.5", "sk_text": "Membuat perkaitan antara komposisi badan dengan kecergasan fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.1", "sp_code": "5.1.1", "sp_text": "Membuat persediaan diri sebelum, semasa dan selepas melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "source_task": "Mengukur tinggi dan berat secara sulit", "authoring_focus": "Mengukur tinggi dan berat secara sulit", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": true, "source_subset_note": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap.", "adaptation_note": "Guru membenarkan pecahan M38: S1 otot teras BT58–59, S2 ukuran sebenar secara sulit BT60–61. Baris Badan Idaman berkongsi sel minggu38 melalui WordvMerge. Contoh bentuk badan rekaan digunakan tanpa melabel atau mendiagnosis murid. Tiada BMI, sasaran berat atau perbandingan data rakan. Ukuran yang belum diperoleh dicatat untuk susulan.", "privacy_adaptation": true, "privacy_note": "Ukuran sebenar sulit; bentuk badan dibincang melalui contoh rekaan, bukan label murid atau diagnosis.", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": ["Pengelasan bentuk badan murid sebenar daripada rupa tidak dilakukan; contoh rekaan sahaja."], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Bacaan tinggi dan berat ialah maklumat sulit. Jangan menyebut kuat, membuat ranking, pertandingan atau meminta rakan mencatat.", "Tiada BMI, sasaran menurunkan berat, diet atau label tubuh murid. Contoh rekaan tidak dipindahkan kepada murid sebenar.", "Jika murid tidak selesa, guru mengurus giliran secara peribadi mengikut prosedur sekolah. Jangan memaksa atau mereka bacaan.", "Semua murid berhenti bergerak ketika perhatian guru pada alat atau rekod. Jika pengawasan tidak mencukupi, tangguhkan pengukuran atau gerakan."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Ukuran sebenar secara sulit dan mengenal komponen badan", "objective": "Murid dapat mengukur ketinggian dan menimbang berat badan dengan bantuan guru secara sulit.", "success_criteria": ["Mendapatkan bacaan tinggi dan berat sebenar pada giliran sendiri; bacaan atau giliran yang belum lengkap direkod.", "Mengenal tulang, otot, organ dan lemak serta istilah bentuk badan pada contoh rekaan sahaja."], "prior_knowledge": "Murid tahu perlu menunggu giliran dan memberitahu guru jika tidak selesa.", "equipment": [{"item": "Alat pengukur tinggi yang dipasang tegak dan penimbang stabil", "quantity": "Satu set yang berfungsi dan boleh dibaca guru.", "use": "Mengukur tinggi serta berat sebenar dengan bantuan guru, bukan anggaran daripada rupa."}, {"item": "Rekod individu dan pen guru", "quantity": "Satu rekod sulit setiap murid serta pen guru.", "use": "Mencatat tinggi dalam cm, berat dalam kg, tarikh dan bantuan. Rekod disimpan tertutup."}, {"item": "Buku teks BT60–61 dan rajah contoh guru", "quantity": "Satu paparan komponen badan serta tiga rajah watak rekaan yang dilabel contoh sahaja.", "use": "Mengenal tulang, otot, organ dan lemak serta istilah bentuk badan tanpa menilai tubuh murid."}, {"item": "Kon penanda", "quantity": "Empat kon di luar ruang pijakan.", "use": "Menandakan tempat menunggu, ruang gerak ringan dan laluan ke tempat ukuran."}, {"item": "Air minuman sendiri", "quantity": "Mengikut keperluan murid.", "use": "Peluang minum serta rehat; tiada ukuran dibuat ketika murid masih bergerak."}], "preparation": ["Periksa penimbang menunjukkan sifar dan berada di lantai keras yang rata. Alat tinggi tegak dan tidak bergerak.", "Letakkan tempat ukuran supaya guru masih melihat semua murid. Bacaan hanya disebut perlahan kepada murid yang diukur; rekod tidak dipamerkan atau dibaca rakan.", "Sediakan rajah komponen badan guru berdasarkan nama BT60 dan tiga watak rekaan untuk istilah BT61. Tiada data atau gambar tubuh murid digunakan.", "Andaian perancangan satu guru/satu set alat: sehingga tujuh giliran dua minit dalam dua fasa amali. Kurangkan jika perlu; baki murid dijadualkan susulan. Ini bukan janji seluruh kelas diukur dalam satu sesi."], "organisation": ["Guru memanggil seorang murid ke alat. Yang lain menunggu tenang dalam pandangan dan tidak berkumpul untuk melihat bacaan.", "Pergerakan ringan setempat hanya apabila guru dapat mengawasi. Semua berhenti dan duduk tenang semasa guru membaca alat atau menulis rekod.", "Murid yang belum diukur boleh mempelajari komponen dan contoh rekaan, tetapi itu bukan pengganti pengukuran sendiri. Tiada bacaan disalin daripada contoh atau rekod lama sebagai bacaan baharu."], "movement_cues": ["Tinggi: tanggalkan kasut di tempat selamat, berdiri tegak selesa dengan kaki rapat dan pandang hadapan. Guru melaras penanda di atas kepala tanpa menekan.", "Berat: naik seorang demi seorang pada penimbang yang stabil, berdiri diam dan turun selepas guru selesai membaca. Jangan melompat pada alat.", "Rekod tinggi cm dan berat kg serta tarikh sebenar. Buku memberi contoh unit meter; rekod cm ialah penyesuaian guru yang dilabel, bukan menukar angka sumber secara senyap.", "Komponen badan termasuk tulang, otot, organ dan lemak. Contoh organ ialah paru-paru atau jantung; lemak juga diperlukan dalam badan dan bukan sesuatu yang perlu dihapuskan.", "Istilah kurus, sederhana dan berlebihan berat badan diperkenalkan melalui tiga rajah watak rekaan berlabel. Rajah untuk mengenal istilah, bukan cara mendiagnosis diri atau rakan daripada rupa. Penilaian kesihatan sebenar oleh petugas yang sesuai."], "timing_note": "Satu guru dan satu set alat: sehingga empat giliran dua minit dalam fasa sembilan minit dan tiga giliran dalam fasa tujuh minit, dengan baki masa untuk arahan/peralihan. Giliran sebenar bergantung pada murid; semua 30 minit termasuk rutin dan penyejukan.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Berdiri diam. Cikgu baca dan catat untuk kamu sahaja. Jika belum mendapat giliran, kita catat untuk sesi susulan.", "pupils_do": "Murid menggunakan alat pada gilirannya dan menjaga privasi rakan.", "teacher_checks": "Guru semak dua bacaan sebenar dengan unit serta tarikh, bukan membandingkan tubuh atau meneka angka."}, "bbm": ["Alat pengukur tinggi yang dipasang tegak dan penimbang stabil — Satu set yang berfungsi dan boleh dibaca guru.", "Rekod individu dan pen guru — Satu rekod sulit setiap murid serta pen guru.", "Buku teks BT60–61 dan rajah contoh guru — Satu paparan komponen badan serta tiga rajah watak rekaan yang dilabel contoh sahaja.", "Kon penanda — Empat kon di luar ruang pijakan.", "Air minuman sendiri — Mengikut keperluan murid.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Alat pengukur tinggi yang dipasang tegak dan penimbang stabil", "Rekod individu dan pen guru", "Buku teks BT60–61 dan rajah contoh guru", "Kon penanda", "Air minuman sendiri"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Kenal alat dan empat komponen", "minutes": 4, "teacher": ["Guru menunjukkan cara berdiri pada alat tanpa memaparkan bacaan seseorang.", "Guru merujuk rajah untuk menyebut tulang, otot, organ dan lemak.", "Guru memperkenalkan tiga istilah pada watak rekaan sahaja; terangkan rupa tidak cukup untuk menentukan kesihatan seseorang."], "pupils": ["Murid meniru berdiri tegak di tempat sendiri tanpa berebut alat.", "Murid menyebut empat komponen dengan bantuan.", "Murid mengenal label pada contoh rekaan tanpa menamakan bentuk badan rakan."], "check": "Pengetahuan diajar kepada semua; pengukuran tetap memerlukan giliran sebenar.", "resources": ["Alat ukuran", "Buku/rajah guru"]}, {"name": "Giliran ukuran pertama", "minutes": 9, "teacher": ["Gunakan satu minit untuk mengulang aturan privasi serta laluan.", "Panggil sehingga empat murid, sekitar dua minit setiap orang untuk tinggi, berat, rekod dan peralihan. Bacaan disebut perlahan.", "Minta yang lain berhenti dan duduk tenang apabila perhatian guru pada bacaan. Jika guru dapat mengawasi antara giliran, izinkan langkah setempat ringan seketika."], "pupils": ["Murid yang dipanggil menggunakan alat tinggi dan penimbang dengan bantuan guru.", "Murid mendengar bacaan sendiri dan turun dengan selamat.", "Murid yang menunggu menjaga privasi, menyemak pakaian dan meminta minum atau rehat apabila perlu."], "check": "Guru merekod kedua-dua bacaan sebenar, unit dan tarikh; belum lengkap tidak diisi anggaran.", "resources": ["Pengukur tinggi", "Penimbang", "Rekod sulit"]}, {"name": "Giliran susulan dan semakan pengetahuan", "minutes": 7, "teacher": ["Panggil sehingga tiga murid lagi sekitar dua minit setiap seorang jika keadaan membenarkan.", "Gunakan baki masa singkat antara atau selepas giliran untuk soalan empat komponen dan label watak rekaan kepada murid yang belum didengar. Jangan mengambil masa membaca alat untuk mengawasi gerakan serentak.", "Catat nama yang belum mendapat dua bacaan dan jadualkan slot susulan; simpan rekod sebelum penyejukan."], "pupils": ["Murid menjalani giliran sebenar atau menunggu dengan tenang.", "Murid yang ditanya menyebut tulang, otot, organ dan lemak serta mengenal istilah pada contoh rekaan.", "Murid menyatakan keperluan bantuan dan tidak meminta melihat rekod rakan."], "check": "Utamakan bacaan dan pengawasan; pengetahuan yang belum sempat disemak juga ditanda susulan.", "resources": ["Alat ukuran", "Rekod sulit", "Rajah guru"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Menggunakan dua alat dengan arahan satu demi satu serta mengenal komponen dengan kata bantu.", "materials": ["Alat tinggi", "Penimbang", "Rekod sulit", "Rajah contoh"], "teacher": ["Guru memimpin posisi berdiri tanpa memaparkan bacaan kepada kelas.", "Beri pilihan lisan bagi tulang, otot, organ dan lemak serta label contoh rekaan."], "pupil_steps": ["Sediakan diri, tunggu dipanggil dan beritahu jika tidak selesa.", "Berdiri untuk tinggi dan berat sebenar pada giliran sendiri; jika belum giliran, tandakan belum diukur.", "Sebut tulang, otot, organ dan lemak dengan bantuan; kenal kurus, sederhana dan berlebihan berat badan pada watak rekaan sahaja.", "Semak keadaan diri selepas aktiviti, minum jika perlu dan jangan berkongsi bacaan rakan."], "product": "Dua bacaan sendiri jika sempat dan respons pengetahuan dengan bantuan.", "criterion": "Bacaan benar dan sulit; contoh rekaan atau pemerhatian rakan tidak menggantikan ukuran sendiri.", "next_step": "Susuli alat atau jawapan yang belum lengkap secara peribadi.", "example": {"teacher": "Boleh kita meneka berat daripada rupa?", "pupil": "Tidak. Gunakan alat dengan bantuan guru."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Mengukur tinggi dan berat serta menjaga privasi rekod.", "materials": ["Alat ukuran", "Rekod sulit", "Rajah"], "teacher": ["Semak posisi kaki dan bacaan stabil.", "Tanya komponen serta istilah pada contoh rekaan selepas bacaan, bukan di hadapan penonton."], "pupil_steps": ["Periksa pakaian dan tunggu giliran.", "Gunakan alat tinggi serta penimbang dan dengar bacaan sendiri secara sulit.", "Kenal tulang, otot, organ dan lemak serta label tiga contoh rekaan, bukan tubuh rakan.", "Ikut penyejukan, minum dan kemas barang sendiri selepas arahan."], "product": "Dua ukuran individu dan respons komponen/istilah rekaan.", "criterion": "Kedua-dua bacaan sebenar direkod dengan unit; yang belum diukur kekal tertangguh.", "next_step": "Lengkapkan giliran dan pengetahuan yang belum disemak.", "example": {"teacher": "Siapa boleh membaca rekod ini?", "pupil": "Guru dan saya mengikut arahan, bukan semua rakan."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas posisi semasa ukuran dan penerangan komponen dengan privasi.", "materials": ["Alat ukuran", "Rekod sulit", "Rajah"], "teacher": ["Minta murid menyemak berdiri diam atau unit dengan bantuan, bukan membanding angka.", "Berikan satu contoh organ jika perlu; jangan minta kategori kesihatan diri."], "pupil_steps": ["Sediakan diri dan ambil giliran tanpa berebut.", "Ukur tinggi dan timbang berat sendiri dengan berdiri stabil.", "Sebut tulang, otot, organ dan lemak; beri satu contoh organ dan kenal tiga istilah pada watak rekaan sahaja.", "Semak keadaan diri selepas aktiviti dan simpan bacaan secara sulit."], "product": "Dua ukuran serta respons pengetahuan dan privasi.", "criterion": "Posisi serta bacaan tepat mengikut alat; tiada diagnosis atau perbandingan rakan.", "next_step": "Susuli ukuran yang belum stabil tanpa membuat anggaran.", "example": {"teacher": "Apakah contoh organ dalam badan?", "pupil": "Paru-paru atau jantung."}}}, "differentiation_delivery": {"common_task": "Murid dapat mengukur ketinggian dan menimbang berat badan dengan bantuan guru secara sulit.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bimbing Peneroka di alat tanpa mengabaikan kelas.", "Semak dua bacaan Pembina.", "Dengar contoh organ Pencabar tanpa menambah perbandingan angka."], "individual_check": "Mendapatkan bacaan tinggi dan berat sebenar pada giliran sendiri; bacaan atau giliran yang belum lengkap direkod.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian guru ketika setiap murid menggunakan alat sebenar.", "evidence": "Tinggi cm dan berat kg yang benar-benar diukur, dengan tarikh dan bantuan.", "criterion": "Kedua-dua bacaan sendiri diperlukan; giliran belum selesai, rekod lama atau contoh rekaan bukan bukti pengukuran baharu.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Kod murid: ____", "Tinggi ____ cm; tarikh ____", "Berat ____ kg; tarikh ____", "Alat/petugas/bantuan: ____", "Belum diukur/susulan: ____"]}, "pbd_complementary": {"4.5.1": {"method": "Soal jawab individu berpandukan rajah guru.", "evidence": "Murid mengenal tulang, otot, organ dan lemak.", "criterion": "Keempat-empat komponen dikenal dengan kata bantu jika perlu; lemak tidak dilabel semuanya buruk.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Tulang: ____", "Otot: ____", "Organ: ____", "Lemak: ____", "Bantuan/belum didengar: ____"]}, "4.5.2": {"method": "Pengenalan istilah pada rajah watak rekaan berlabel.", "evidence": "Murid mengenal kurus, sederhana dan berlebihan berat badan pada contoh rekaan sahaja.", "criterion": "Istilah dikenal tanpa menilai atau melabel tubuh murid. Ini bukan diagnosis daripada rupa, ukuran atau BMI.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Contoh rekaan kurus: ____", "Contoh rekaan sederhana: ____", "Contoh rekaan berlebihan berat badan: ____", "Bantuan/batas penilaian: ____"]}, "5.1.1": {"method": "Pemerhatian persediaan sebelum, semasa dan selepas aktiviti.", "evidence": "Sebelum: pakaian dan keadaan diri; semasa: giliran selamat dan maklumkan keperluan; selepas: penyejukan, minum serta urus barang.", "criterion": "Ketiga-tiga waktu diperhatikan berasingan; permintaan rehat dan privasi dihormati.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Sebelum: ____", "Semasa: ____", "Selepas: ____", "Bantuan/belum diperhatikan: ____"]}}, "intervention": ["Jadualkan pengukuran sulit bagi semua murid yang belum mendapat tinggi dan berat. Jangan isi angka contoh atau angka jangkaan.", "Jika bacaan tidak stabil, semak alat dan ulang pada slot sesuai; bukan meneka. Ulang komponen atau label rekaan yang belum dikenal melalui kata bantu."], "book_pages_text": "60, 61", "sp_focus": "", "sp_display": "3.5.1", "complementary": [{"standard_key": "4.5.1", "sp_code": "4.5.1", "sp_text": "Mengenal pasti komponen dalam badan iaitu tulang, otot, organ dan lemak.", "sk_code": "4.5", "sk_text": "Membuat perkaitan antara komposisi badan dengan kecergasan fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.5.2", "sp_code": "4.5.2", "sp_text": "Mengenali bentuk badan kurus, sederhana dan berlebihan berat badan.", "sk_code": "4.5", "sk_text": "Membuat perkaitan antara komposisi badan dengan kecergasan fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.1", "sp_code": "5.1.1", "sp_text": "Membuat persediaan diri sebelum, semasa dan selepas melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}], "draft_sha256": "a7f2e712ab24e90cc9d033e0eaec454dc30e304c97871f363e7a9acec60004f4"}'::jsonb,'[{"kind": "title", "text": "Minggu 38 Sesi 2 — Ukuran sebenar secara sulit dan mengenal komponen badan"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W38-S2"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 8: Cergas dan Mantap"}, {"kind": "p", "text": "Tajuk buku teks: Badan Idaman"}, {"kind": "p", "text": "Aktiviti guru: Ukuran sebenar secara sulit dan mengenal komponen badan"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 60, 61."}, {"kind": "p", "text": "Satu guru dan satu set alat: sehingga empat giliran dua minit dalam fasa sembilan minit dan tiga giliran dalam fasa tujuh minit, dengan baki masa untuk arahan/peralihan. Giliran sebenar bergantung pada murid; semua 30 minit termasuk rutin dan penyejukan."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.5: Melakukan aktiviti yang melibatkan komposisi badan."}, {"kind": "p", "text": "SP utama 3.5.1: Mengukur ketinggian dan menimbang berat badan."}, {"kind": "p", "text": "SK sokongan 4.5: Membuat perkaitan antara komposisi badan dengan kecergasan fizikal."}, {"kind": "p", "text": "SP sokongan 4.5.1: Mengenal pasti komponen dalam badan iaitu tulang, otot, organ dan lemak."}, {"kind": "p", "text": "SK sokongan 4.5: Membuat perkaitan antara komposisi badan dengan kecergasan fizikal."}, {"kind": "p", "text": "SP sokongan 4.5.2: Mengenali bentuk badan kurus, sederhana dan berlebihan berat badan."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.1: Membuat persediaan diri sebelum, semasa dan selepas melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "Fokus dan bantuan mengikut sesi; jangan menyamakan ansur maju, pemerhatian atau bantuan dengan semua lakuan sumber yang lengkap."}, {"kind": "p", "text": "Ukuran sebenar sulit; bentuk badan dibincang melalui contoh rekaan, bukan label murid atau diagnosis."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat mengukur ketinggian dan menimbang berat badan dengan bantuan guru secara sulit."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Mendapatkan bacaan tinggi dan berat sebenar pada giliran sendiri; bacaan atau giliran yang belum lengkap direkod."}, {"kind": "p", "text": "2. Mengenal tulang, otot, organ dan lemak serta istilah bentuk badan pada contoh rekaan sahaja."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid tahu perlu menunggu giliran dan memberitahu guru jika tidak selesa."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Alat pengukur tinggi yang dipasang tegak dan penimbang stabil"}, {"kind": "p", "text": "Keperluan: Satu set yang berfungsi dan boleh dibaca guru."}, {"kind": "p", "text": "Kegunaan: Mengukur tinggi serta berat sebenar dengan bantuan guru, bukan anggaran daripada rupa."}, {"kind": "label", "text": "Rekod individu dan pen guru"}, {"kind": "p", "text": "Keperluan: Satu rekod sulit setiap murid serta pen guru."}, {"kind": "p", "text": "Kegunaan: Mencatat tinggi dalam cm, berat dalam kg, tarikh dan bantuan. Rekod disimpan tertutup."}, {"kind": "label", "text": "Buku teks BT60–61 dan rajah contoh guru"}, {"kind": "p", "text": "Keperluan: Satu paparan komponen badan serta tiga rajah watak rekaan yang dilabel contoh sahaja."}, {"kind": "p", "text": "Kegunaan: Mengenal tulang, otot, organ dan lemak serta istilah bentuk badan tanpa menilai tubuh murid."}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: Empat kon di luar ruang pijakan."}, {"kind": "p", "text": "Kegunaan: Menandakan tempat menunggu, ruang gerak ringan dan laluan ke tempat ukuran."}, {"kind": "label", "text": "Air minuman sendiri"}, {"kind": "p", "text": "Keperluan: Mengikut keperluan murid."}, {"kind": "p", "text": "Kegunaan: Peluang minum serta rehat; tiada ukuran dibuat ketika murid masih bergerak."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Periksa penimbang menunjukkan sifar dan berada di lantai keras yang rata. Alat tinggi tegak dan tidak bergerak."}, {"kind": "p", "text": "2. Letakkan tempat ukuran supaya guru masih melihat semua murid. Bacaan hanya disebut perlahan kepada murid yang diukur; rekod tidak dipamerkan atau dibaca rakan."}, {"kind": "p", "text": "3. Sediakan rajah komponen badan guru berdasarkan nama BT60 dan tiga watak rekaan untuk istilah BT61. Tiada data atau gambar tubuh murid digunakan."}, {"kind": "p", "text": "4. Andaian perancangan satu guru/satu set alat: sehingga tujuh giliran dua minit dalam dua fasa amali. Kurangkan jika perlu; baki murid dijadualkan susulan. Ini bukan janji seluruh kelas diukur dalam satu sesi."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Guru memanggil seorang murid ke alat. Yang lain menunggu tenang dalam pandangan dan tidak berkumpul untuk melihat bacaan."}, {"kind": "p", "text": "2. Pergerakan ringan setempat hanya apabila guru dapat mengawasi. Semua berhenti dan duduk tenang semasa guru membaca alat atau menulis rekod."}, {"kind": "p", "text": "3. Murid yang belum diukur boleh mempelajari komponen dan contoh rekaan, tetapi itu bukan pengganti pengukuran sendiri. Tiada bacaan disalin daripada contoh atau rekod lama sebagai bacaan baharu."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Tinggi: tanggalkan kasut di tempat selamat, berdiri tegak selesa dengan kaki rapat dan pandang hadapan. Guru melaras penanda di atas kepala tanpa menekan."}, {"kind": "p", "text": "2. Berat: naik seorang demi seorang pada penimbang yang stabil, berdiri diam dan turun selepas guru selesai membaca. Jangan melompat pada alat."}, {"kind": "p", "text": "3. Rekod tinggi cm dan berat kg serta tarikh sebenar. Buku memberi contoh unit meter; rekod cm ialah penyesuaian guru yang dilabel, bukan menukar angka sumber secara senyap."}, {"kind": "p", "text": "4. Komponen badan termasuk tulang, otot, organ dan lemak. Contoh organ ialah paru-paru atau jantung; lemak juga diperlukan dalam badan dan bukan sesuatu yang perlu dihapuskan."}, {"kind": "p", "text": "5. Istilah kurus, sederhana dan berlebihan berat badan diperkenalkan melalui tiga rajah watak rekaan berlabel. Rajah untuk mengenal istilah, bukan cara mendiagnosis diri atau rakan daripada rupa. Penilaian kesihatan sebenar oleh petugas yang sesuai."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Alat pengukur tinggi yang dipasang tegak dan penimbang stabil — Satu set yang berfungsi dan boleh dibaca guru."}, {"kind": "p", "text": "2. Rekod individu dan pen guru — Satu rekod sulit setiap murid serta pen guru."}, {"kind": "p", "text": "3. Buku teks BT60–61 dan rajah contoh guru — Satu paparan komponen badan serta tiga rajah watak rekaan yang dilabel contoh sahaja."}, {"kind": "p", "text": "4. Kon penanda — Empat kon di luar ruang pijakan."}, {"kind": "p", "text": "5. Air minuman sendiri — Mengikut keperluan murid."}, {"kind": "p", "text": "6. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Bacaan tinggi dan berat ialah maklumat sulit. Jangan menyebut kuat, membuat ranking, pertandingan atau meminta rakan mencatat."}, {"kind": "p", "text": "5. Tiada BMI, sasaran menurunkan berat, diet atau label tubuh murid. Contoh rekaan tidak dipindahkan kepada murid sebenar."}, {"kind": "p", "text": "6. Jika murid tidak selesa, guru mengurus giliran secara peribadi mengikut prosedur sekolah. Jangan memaksa atau mereka bacaan."}, {"kind": "p", "text": "7. Semua murid berhenti bergerak ketika perhatian guru pada alat atau rekod. Jika pengawasan tidak mencukupi, tangguhkan pengukuran atau gerakan."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Alat pengukur tinggi yang dipasang tegak dan penimbang stabil Rekod individu dan pen guru Buku teks BT60–61 dan rajah contoh guru Kon penanda Air minuman sendiri"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Kenal alat dan empat komponen — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan cara berdiri pada alat tanpa memaparkan bacaan seseorang."}, {"kind": "p", "text": "2. Guru merujuk rajah untuk menyebut tulang, otot, organ dan lemak."}, {"kind": "p", "text": "3. Guru memperkenalkan tiga istilah pada watak rekaan sahaja; terangkan rupa tidak cukup untuk menentukan kesihatan seseorang."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meniru berdiri tegak di tempat sendiri tanpa berebut alat."}, {"kind": "p", "text": "2. Murid menyebut empat komponen dengan bantuan."}, {"kind": "p", "text": "3. Murid mengenal label pada contoh rekaan tanpa menamakan bentuk badan rakan."}, {"kind": "p", "text": "Semakan: Pengetahuan diajar kepada semua; pengukuran tetap memerlukan giliran sebenar."}, {"kind": "p", "text": "Alatan: Alat ukuran Buku/rajah guru"}, {"kind": "h3", "text": "Langkah 4: Giliran ukuran pertama — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Gunakan satu minit untuk mengulang aturan privasi serta laluan."}, {"kind": "p", "text": "2. Panggil sehingga empat murid, sekitar dua minit setiap orang untuk tinggi, berat, rekod dan peralihan. Bacaan disebut perlahan."}, {"kind": "p", "text": "3. Minta yang lain berhenti dan duduk tenang apabila perhatian guru pada bacaan. Jika guru dapat mengawasi antara giliran, izinkan langkah setempat ringan seketika."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid yang dipanggil menggunakan alat tinggi dan penimbang dengan bantuan guru."}, {"kind": "p", "text": "2. Murid mendengar bacaan sendiri dan turun dengan selamat."}, {"kind": "p", "text": "3. Murid yang menunggu menjaga privasi, menyemak pakaian dan meminta minum atau rehat apabila perlu."}, {"kind": "p", "text": "Semakan: Guru merekod kedua-dua bacaan sebenar, unit dan tarikh; belum lengkap tidak diisi anggaran."}, {"kind": "p", "text": "Alatan: Pengukur tinggi Penimbang Rekod sulit"}, {"kind": "h3", "text": "Langkah 5: Giliran susulan dan semakan pengetahuan — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Panggil sehingga tiga murid lagi sekitar dua minit setiap seorang jika keadaan membenarkan."}, {"kind": "p", "text": "2. Gunakan baki masa singkat antara atau selepas giliran untuk soalan empat komponen dan label watak rekaan kepada murid yang belum didengar. Jangan mengambil masa membaca alat untuk mengawasi gerakan serentak."}, {"kind": "p", "text": "3. Catat nama yang belum mendapat dua bacaan dan jadualkan slot susulan; simpan rekod sebelum penyejukan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menjalani giliran sebenar atau menunggu dengan tenang."}, {"kind": "p", "text": "2. Murid yang ditanya menyebut tulang, otot, organ dan lemak serta mengenal istilah pada contoh rekaan."}, {"kind": "p", "text": "3. Murid menyatakan keperluan bantuan dan tidak meminta melihat rekod rakan."}, {"kind": "p", "text": "Semakan: Utamakan bacaan dan pengawasan; pengetahuan yang belum sempat disemak juga ditanda susulan."}, {"kind": "p", "text": "Alatan: Alat ukuran Rekod sulit Rajah guru"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Berdiri diam. Cikgu baca dan catat untuk kamu sahaja. Jika belum mendapat giliran, kita catat untuk sesi susulan."}, {"kind": "p", "text": "Murid: Murid menggunakan alat pada gilirannya dan menjaga privasi rakan."}, {"kind": "p", "text": "Semakan guru: Guru semak dua bacaan sebenar dengan unit serta tarikh, bukan membandingkan tubuh atau meneka angka."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W38-S2"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat mengukur ketinggian dan menimbang berat badan dengan bantuan guru secara sulit."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bimbing Peneroka di alat tanpa mengabaikan kelas."}, {"kind": "p", "text": "2. Semak dua bacaan Pembina."}, {"kind": "p", "text": "3. Dengar contoh organ Pencabar tanpa menambah perbandingan angka."}, {"kind": "p", "text": "Semakan individu: Mendapatkan bacaan tinggi dan berat sebenar pada giliran sendiri; bacaan atau giliran yang belum lengkap direkod."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Menggunakan dua alat dengan arahan satu demi satu serta mengenal komponen dengan kata bantu."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Alat tinggi"}, {"kind": "p", "text": "2. Penimbang"}, {"kind": "p", "text": "3. Rekod sulit"}, {"kind": "p", "text": "4. Rajah contoh"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin posisi berdiri tanpa memaparkan bacaan kepada kelas."}, {"kind": "p", "text": "2. Beri pilihan lisan bagi tulang, otot, organ dan lemak serta label contoh rekaan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sediakan diri, tunggu dipanggil dan beritahu jika tidak selesa."}, {"kind": "p", "text": "2. Berdiri untuk tinggi dan berat sebenar pada giliran sendiri; jika belum giliran, tandakan belum diukur."}, {"kind": "p", "text": "3. Sebut tulang, otot, organ dan lemak dengan bantuan; kenal kurus, sederhana dan berlebihan berat badan pada watak rekaan sahaja."}, {"kind": "p", "text": "4. Semak keadaan diri selepas aktiviti, minum jika perlu dan jangan berkongsi bacaan rakan."}, {"kind": "p", "text": "Contoh guru: Boleh kita meneka berat daripada rupa?"}, {"kind": "p", "text": "Contoh respons murid: Tidak. Gunakan alat dengan bantuan guru."}, {"kind": "p", "text": "Hasil individu: Dua bacaan sendiri jika sempat dan respons pengetahuan dengan bantuan."}, {"kind": "p", "text": "Kriteria: Bacaan benar dan sulit; contoh rekaan atau pemerhatian rakan tidak menggantikan ukuran sendiri."}, {"kind": "p", "text": "Susulan: Susuli alat atau jawapan yang belum lengkap secara peribadi."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Mengukur tinggi dan berat serta menjaga privasi rekod."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Alat ukuran"}, {"kind": "p", "text": "2. Rekod sulit"}, {"kind": "p", "text": "3. Rajah"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Semak posisi kaki dan bacaan stabil."}, {"kind": "p", "text": "2. Tanya komponen serta istilah pada contoh rekaan selepas bacaan, bukan di hadapan penonton."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Periksa pakaian dan tunggu giliran."}, {"kind": "p", "text": "2. Gunakan alat tinggi serta penimbang dan dengar bacaan sendiri secara sulit."}, {"kind": "p", "text": "3. Kenal tulang, otot, organ dan lemak serta label tiga contoh rekaan, bukan tubuh rakan."}, {"kind": "p", "text": "4. Ikut penyejukan, minum dan kemas barang sendiri selepas arahan."}, {"kind": "p", "text": "Contoh guru: Siapa boleh membaca rekod ini?"}, {"kind": "p", "text": "Contoh respons murid: Guru dan saya mengikut arahan, bukan semua rakan."}, {"kind": "p", "text": "Hasil individu: Dua ukuran individu dan respons komponen/istilah rekaan."}, {"kind": "p", "text": "Kriteria: Kedua-dua bacaan sebenar direkod dengan unit; yang belum diukur kekal tertangguh."}, {"kind": "p", "text": "Susulan: Lengkapkan giliran dan pengetahuan yang belum disemak."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas posisi semasa ukuran dan penerangan komponen dengan privasi."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Alat ukuran"}, {"kind": "p", "text": "2. Rekod sulit"}, {"kind": "p", "text": "3. Rajah"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minta murid menyemak berdiri diam atau unit dengan bantuan, bukan membanding angka."}, {"kind": "p", "text": "2. Berikan satu contoh organ jika perlu; jangan minta kategori kesihatan diri."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sediakan diri dan ambil giliran tanpa berebut."}, {"kind": "p", "text": "2. Ukur tinggi dan timbang berat sendiri dengan berdiri stabil."}, {"kind": "p", "text": "3. Sebut tulang, otot, organ dan lemak; beri satu contoh organ dan kenal tiga istilah pada watak rekaan sahaja."}, {"kind": "p", "text": "4. Semak keadaan diri selepas aktiviti dan simpan bacaan secara sulit."}, {"kind": "p", "text": "Contoh guru: Apakah contoh organ dalam badan?"}, {"kind": "p", "text": "Contoh respons murid: Paru-paru atau jantung."}, {"kind": "p", "text": "Hasil individu: Dua ukuran serta respons pengetahuan dan privasi."}, {"kind": "p", "text": "Kriteria: Posisi serta bacaan tepat mengikut alat; tiada diagnosis atau perbandingan rakan."}, {"kind": "p", "text": "Susulan: Susuli ukuran yang belum stabil tanpa membuat anggaran."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.5.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian guru ketika setiap murid menggunakan alat sebenar."}, {"kind": "p", "text": "Bukti: Tinggi cm dan berat kg yang benar-benar diukur, dengan tarikh dan bantuan."}, {"kind": "p", "text": "Kriteria: Kedua-dua bacaan sendiri diperlukan; giliran belum selesai, rekod lama atau contoh rekaan bukan bukti pengukuran baharu."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Kod murid: ____"}, {"kind": "p", "text": "2. Tinggi ____ cm; tarikh ____"}, {"kind": "p", "text": "3. Berat ____ kg; tarikh ____"}, {"kind": "p", "text": "4. Alat/petugas/bantuan: ____"}, {"kind": "p", "text": "5. Belum diukur/susulan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.5.1"}, {"kind": "p", "text": "Kaedah: Soal jawab individu berpandukan rajah guru."}, {"kind": "p", "text": "Bukti: Murid mengenal tulang, otot, organ dan lemak."}, {"kind": "p", "text": "Kriteria: Keempat-empat komponen dikenal dengan kata bantu jika perlu; lemak tidak dilabel semuanya buruk."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Tulang: ____"}, {"kind": "p", "text": "2. Otot: ____"}, {"kind": "p", "text": "3. Organ: ____"}, {"kind": "p", "text": "4. Lemak: ____"}, {"kind": "p", "text": "5. Bantuan/belum didengar: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 4.5.2"}, {"kind": "p", "text": "Kaedah: Pengenalan istilah pada rajah watak rekaan berlabel."}, {"kind": "p", "text": "Bukti: Murid mengenal kurus, sederhana dan berlebihan berat badan pada contoh rekaan sahaja."}, {"kind": "p", "text": "Kriteria: Istilah dikenal tanpa menilai atau melabel tubuh murid. Ini bukan diagnosis daripada rupa, ukuran atau BMI."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Contoh rekaan kurus: ____"}, {"kind": "p", "text": "2. Contoh rekaan sederhana: ____"}, {"kind": "p", "text": "3. Contoh rekaan berlebihan berat badan: ____"}, {"kind": "p", "text": "4. Bantuan/batas penilaian: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian persediaan sebelum, semasa dan selepas aktiviti."}, {"kind": "p", "text": "Bukti: Sebelum: pakaian dan keadaan diri; semasa: giliran selamat dan maklumkan keperluan; selepas: penyejukan, minum serta urus barang."}, {"kind": "p", "text": "Kriteria: Ketiga-tiga waktu diperhatikan berasingan; permintaan rehat dan privasi dihormati."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Sebelum: ____"}, {"kind": "p", "text": "2. Semasa: ____"}, {"kind": "p", "text": "3. Selepas: ____"}, {"kind": "p", "text": "4. Bantuan/belum diperhatikan: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Jadualkan pengukuran sulit bagi semua murid yang belum mendapat tinggi dan berat. Jangan isi angka contoh atau angka jangkaan."}, {"kind": "p", "text": "2. Jika bacaan tidak stabil, semak alat dan ulang pada slot sesuai; bukan meneka. Ulang komponen atau label rekaan yang belum dikenal melalui kata bantu."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Guru membenarkan pecahan M38: S1 otot teras BT58–59, S2 ukuran sebenar secara sulit BT60–61. Baris Badan Idaman berkongsi sel minggu38 melalui WordvMerge. Contoh bentuk badan rekaan digunakan tanpa melabel atau mendiagnosis murid. Tiada BMI, sasaran berat atau perbandingan data rakan. Ukuran yang belum diperoleh dicatat untuk susulan.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb)


